-- Minimum Stress — full schema, generated from supabase/migrations/
--
-- Generated by scripts/build-apply-sql.mjs — edit the migrations, not this.
--
-- Safe to run more than once. Every statement is guarded, so pasting this
-- into a project that already has some of it is boring rather than a
-- transaction that aborts halfway and leaves you guessing what landed.
--
-- 0000_supabase_stubs.sql is deliberately NOT included: it recreates what
-- Supabase already provides and exists only so the test suite can run the
-- migrations against a bare Postgres.

-- ===================================================================
-- 0001_schema.sql
-- ===================================================================

-- Minimum Stress — core schema
--
-- Not yet applied to a live project. Written against the data model in the
-- Phase 1 plan; run `supabase db push` (or paste into the SQL editor) once
-- Supabase keys are available, then read it back with `supabase db diff` to
-- confirm nothing drifted before trusting it in production.
--
-- Money columns mirror src/lib/money.ts's BookingMoney type field-for-field,
-- because a booking freezes the quote that produced it — a host raising their
-- rate later must never rewrite what a past booking cost.

-- No pgcrypto extension: gen_random_uuid() has been core Postgres since 13 and
-- Supabase runs 15+, so requiring the extension would only narrow where these
-- migrations can run.

-- Every statement in this file is safe to re-run. Postgres has no
-- `create type if not exists`, hence the wrapper; tables and indexes use the
-- built-in guard.
--
-- This matters more than it looks. Applying the full script to a project that
-- already has most of it should be boring, not a transaction that aborts on
-- line 16 and leaves the reader guessing which half landed.
do $$ begin
  create type space_category as enum ('physical', 'traditional', 'social', 'spirit');
exception when duplicate_object then null; end $$;

do $$ begin
  create type access_type as enum ('keypad', 'lockbox', 'greeter');
exception when duplicate_object then null; end $$;

do $$ begin
  create type restroom_option as enum ('private', 'shared', 'none');
exception when duplicate_object then null; end $$;

do $$ begin
  create type space_status as enum ('pending', 'active', 'delisted');
exception when duplicate_object then null; end $$;

do $$ begin
  create type media_kind as enum ('image', 'video');
exception when duplicate_object then null; end $$;

do $$ begin
  create type payout_schedule as enum ('standard', 'instant');
exception when duplicate_object then null; end $$;

do $$ begin
  create type booking_status as enum (
    'upcoming', 'completed', 'cancelled_by_practitioner', 'cancelled_by_host', 'no_show'
  );
exception when duplicate_object then null; end $$;

do $$ begin
  create type cancelled_by_actor as enum ('practitioner', 'host');
exception when duplicate_object then null; end $$;

do $$ begin
  create type credit_reason as enum ('host_cancellation', 'booking_redemption', 'goodwill_restore');
exception when duplicate_object then null; end $$;

-- ------------------------------------------------------------------
-- profiles
--
-- One row per auth.users row. No "role" column: the brief's Role Select
-- screen ("You can switch anytime from the top of either screen") is a UI
-- entry point, not a database-enforced identity — the same person can host a
-- space and book someone else's on the same account.
-- ------------------------------------------------------------------
create table if not exists profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  display_name text,
  avatar_path text,
  is_pro boolean not null default false,
  pro_since timestamptz,
  stripe_customer_id text unique,
  stripe_connect_account_id text unique,
  stripe_connect_charges_enabled boolean not null default false,
  insurance_doc_path text,
  payout_schedule payout_schedule not null default 'standard',
  notify_bookings boolean not null default true,
  notify_payouts boolean not null default true,
  notify_offers boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- ------------------------------------------------------------------
-- spaces
--
-- room_type is not stored: it is a pure function of category
-- (lib/taxonomy.ts roomTypeFor), so there is exactly one place the two can
-- ever disagree — the lookup table — rather than a column that can drift
-- from it.
--
-- address_line / lat / lng / entry_instructions are private until a
-- practitioner has a confirmed booking on this space. See 0002_rls.sql for
-- how that boundary is actually enforced — column *visibility* rather than
-- a client-side check, so the private fields never leave the server for an
-- unauthorized request in the first place.
-- ------------------------------------------------------------------
create table if not exists spaces (
  id uuid primary key default gen_random_uuid(),
  host_id uuid not null references profiles (id) on delete cascade,
  name text not null,
  category space_category not null,
  hourly_rate_cents integer not null check (hourly_rate_cents > 0),
  capacity integer not null check (capacity > 0),
  access_type access_type not null,
  entry_instructions text not null,
  address_line text not null,
  lat double precision,
  lng double precision,
  accessible boolean,
  restroom restroom_option,
  buffer_minutes integer not null default 0 check (buffer_minutes >= 0),
  status space_status not null default 'pending',
  sublease_doc_path text not null,
  insurance_doc_path text,
  legal_ack_at timestamptz not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create index if not exists spaces_host_id_idx on spaces (host_id);
create index if not exists spaces_status_idx on spaces (status) where status = 'active';

-- ------------------------------------------------------------------
-- space_media
--
-- The brief requires at least one photo or video per listing but never
-- gates step 1 or 2 on anything past that, so this table has no NOT NULL
-- constraint tying it to a minimum count — that rule lives in application
-- validation at submission time, where it can produce a helpful error
-- instead of a database exception.
-- ------------------------------------------------------------------
create table if not exists space_media (
  id uuid primary key default gen_random_uuid(),
  space_id uuid not null references spaces (id) on delete cascade,
  storage_path text not null,
  kind media_kind not null,
  position integer not null default 0,
  created_at timestamptz not null default now()
);

create index if not exists space_media_space_id_idx on space_media (space_id, position);

-- ------------------------------------------------------------------
-- availability
--
-- One row per block, not one row per day. This is what lets a single Monday
-- hold 7-8am, 2-3pm and 5-9pm as three independent rows rather than forcing
-- one start/end pair per weekday.
-- ------------------------------------------------------------------
create table if not exists availability (
  id uuid primary key default gen_random_uuid(),
  space_id uuid not null references spaces (id) on delete cascade,
  weekday smallint not null check (weekday between 0 and 6),
  start_minute smallint not null check (start_minute between 0 and 1439),
  end_minute smallint not null check (end_minute between 1 and 1440),
  constraint availability_ordered check (end_minute > start_minute)
);

create index if not exists availability_space_id_idx on availability (space_id, weekday);

-- ------------------------------------------------------------------
-- bookings
--
-- Every money column is frozen at creation from a src/lib/money.ts Quote —
-- never recomputed from the space's current rate. access_code is generated
-- but withheld from API responses until access_code_revealed_at (target:
-- T-30min), enforced server-side, not by hiding it in the client.
-- ------------------------------------------------------------------
-- on delete restrict, deliberately: a booking is a financial record tied to a
-- Stripe PaymentIntent and possibly a credit_ledger entry. Cascading a space
-- or profile deletion into it would silently destroy the audit trail for money
-- that actually moved. Deleting either has to reckon with its bookings first.
create table if not exists bookings (
  id uuid primary key default gen_random_uuid(),
  space_id uuid not null references spaces (id) on delete restrict,
  practitioner_id uuid not null references profiles (id) on delete restrict,
  starts_at timestamptz not null,
  ends_at timestamptz not null,
  status booking_status not null default 'upcoming',
  is_instant boolean not null,
  was_pro boolean not null,

  -- Frozen quote — see src/lib/money.ts BookingMoney.
  host_rate_cents integer not null,
  service_fee_cents integer not null,
  instant_fee_cents integer not null,
  pro_discount_cents integer not null,
  credit_applied_cents integer not null,
  total_cents integer not null,
  platform_cents integer not null,

  stripe_payment_intent_id text unique,
  authorized_at timestamptz,
  captured_at timestamptz,

  cancelled_at timestamptz,
  cancelled_by cancelled_by_actor,

  access_code text,
  access_code_revealed_at timestamptz,

  created_at timestamptz not null default now(),

  constraint bookings_ordered check (ends_at > starts_at),
  constraint bookings_cancellation_consistent check (
    (cancelled_at is null) = (cancelled_by is null)
  )
);

create index if not exists bookings_practitioner_id_idx on bookings (practitioner_id);
create index if not exists bookings_space_id_idx on bookings (space_id);
create index if not exists bookings_starts_at_idx on bookings (starts_at) where status = 'upcoming';

-- ------------------------------------------------------------------
-- credit_ledger
--
-- Append-only. The balance is never a stored number — it is always
-- SUM(delta_cents), matching lib/money.ts's creditBalance(). A mutable
-- balance column next to this table would be exactly the bug the prototype
-- had, where credits.balance and credits.ledger could drift apart.
-- ------------------------------------------------------------------
create table if not exists credit_ledger (
  id uuid primary key default gen_random_uuid(),
  practitioner_id uuid not null references profiles (id) on delete restrict,
  delta_cents integer not null,
  reason credit_reason not null,
  booking_id uuid references bookings (id) on delete restrict,
  note text,
  created_at timestamptz not null default now()
);

create index if not exists credit_ledger_practitioner_id_idx on credit_ledger (practitioner_id);

-- security_invoker is load-bearing here, not decoration: without it this
-- view runs as its owner (typically the migration role) and RLS on
-- credit_ledger never applies, so every practitioner's balance becomes
-- readable by anyone granted select on the view. With it, the view enforces
-- exactly the same row policies the base table does for the querying user.
create or replace view credit_balances
  with (security_invoker = true) as
  select practitioner_id, coalesce(sum(delta_cents), 0)::integer as balance_cents
  from credit_ledger
  group by practitioner_id;


-- ===================================================================
-- 0002_rls.sql
-- ===================================================================

-- Row Level Security
--
-- Two settings from the brief stay exactly as configured and this migration
-- does not touch them: RLS is enabled project-wide, and auto-expose-new-tables
-- stays off, so a table only becomes reachable once deliberately granted here.
--
-- The organising rule, because getting this wrong is how address_line leaks:
--
--   Base tables are owner-only. authenticated may reach its own rows;
--     anon may not reach them at all.
--   Anything public goes through a security *definer* view, whose safety comes
--     from its explicit column list and WHERE clause rather than from RLS.
--   Anything per-user goes through a security *invoker* view, so the caller's
--     own row policies still apply.
--
-- The distinction is load-bearing. An invoker view over a table the caller has
-- no grant on simply errors, so "public subset" views cannot be invoker; and a
-- definer view over per-user data bypasses RLS and would hand every
-- practitioner's balance to whoever asked, so per-user views cannot be definer.
--
-- Writes to bookings and credit_ledger happen server-side under the service
-- role, never from the client: a cancellation has to void or capture a Stripe
-- PaymentIntent and write a ledger row in one transaction, and RLS can gate who
-- writes a row but cannot make that write atomic with an external API call.

-- `create policy` has no IF NOT EXISTS, so re-running this file would abort on
-- the first one that already existed. Clearing them first makes the file
-- declarative: what follows is the complete set, and applying it twice is
-- boring rather than a half-applied transaction.
--
-- Scoped to this app's own tables by name, so it cannot reach anything
-- Supabase manages.
do $$
declare existing record;
begin
  for existing in
    select policyname, tablename from pg_policies
    where schemaname = 'public'
      and tablename in (
        'profiles', 'spaces', 'space_media', 'availability', 'bookings', 'credit_ledger'
      )
  loop
    execute format('drop policy if exists %I on public.%I', existing.policyname, existing.tablename);
  end loop;
end $$;

alter table profiles enable row level security;
alter table spaces enable row level security;
alter table space_media enable row level security;
alter table availability enable row level security;
alter table bookings enable row level security;
alter table credit_ledger enable row level security;

-- ------------------------------------------------------------------
-- Table privileges
--
-- Not redundant with the policies below: a policy narrows which rows a role
-- may touch, a GRANT decides whether it may touch the table at all. With
-- auto-expose off there are no defaults, so a policy without a matching grant
-- is dead code — the role is refused before RLS is ever consulted.
-- ------------------------------------------------------------------

grant select, insert, update on profiles to authenticated;
grant select, insert, update, delete on spaces to authenticated;
grant select, insert, update, delete on space_media to authenticated;
grant select, insert, update, delete on availability to authenticated;
grant select on bookings to authenticated;
grant select on credit_ledger to authenticated;

-- ------------------------------------------------------------------
-- profiles
-- ------------------------------------------------------------------

create policy "profiles: read own row"
  on profiles for select
  using (id = auth.uid());

create policy "profiles: insert own row"
  on profiles for insert
  with check (id = auth.uid());

create policy "profiles: update own row"
  on profiles for update
  using (id = auth.uid())
  with check (id = auth.uid());

-- ------------------------------------------------------------------
-- spaces — host-only at the table. Practitioners never select from it
-- directly; they read spaces_public, and the private fields come from
-- space_access_details() once they hold a booking.
-- ------------------------------------------------------------------

create policy "spaces: host reads own rows, any status"
  on spaces for select
  using (host_id = auth.uid());

create policy "spaces: host inserts own rows"
  on spaces for insert
  with check (host_id = auth.uid());

create policy "spaces: host updates own rows"
  on spaces for update
  using (host_id = auth.uid())
  with check (host_id = auth.uid());

create policy "spaces: host deletes own rows"
  on spaces for delete
  using (host_id = auth.uid());

-- ------------------------------------------------------------------
-- space_media / availability — host-only at the table, same as spaces.
-- Public reads go through the *_public views further down.
-- ------------------------------------------------------------------

create policy "space_media: host manages own space's media"
  on space_media for all
  using (exists (select 1 from spaces s where s.id = space_id and s.host_id = auth.uid()))
  with check (exists (select 1 from spaces s where s.id = space_id and s.host_id = auth.uid()));

create policy "availability: host manages own space's schedule"
  on availability for all
  using (exists (select 1 from spaces s where s.id = space_id and s.host_id = auth.uid()))
  with check (exists (select 1 from spaces s where s.id = space_id and s.host_id = auth.uid()));

-- ------------------------------------------------------------------
-- bookings / credit_ledger — read-only for the parties involved.
-- ------------------------------------------------------------------

create policy "bookings: practitioner reads own bookings"
  on bookings for select
  using (practitioner_id = auth.uid());

create policy "bookings: host reads bookings on own spaces"
  on bookings for select
  using (exists (select 1 from spaces s where s.id = space_id and s.host_id = auth.uid()));

create policy "credit_ledger: practitioner reads own entries"
  on credit_ledger for select
  using (practitioner_id = auth.uid());

-- ==================================================================
-- Public views — security DEFINER (the default).
--
-- Safety here is structural: the column list decides what exists at all, so
-- address_line, the Stripe identifiers and the document paths are not
-- omitted-but-reachable, they are absent. A future policy change cannot
-- widen them back into view.
-- ==================================================================

-- Dropped first, not just replaced. `create or replace view` can add columns
-- but never remove them, so on a re-run this file would collide with the wider
-- definition a later migration left behind and abort the whole script.
drop view if exists spaces_public;
drop view if exists public_host_profiles;
drop view if exists availability_public;
drop view if exists space_media_public;
drop view if exists credit_balances;
drop view if exists bookings_with_access_code;

create or replace view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, status, created_at
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;

create or replace view public_host_profiles as
  select id, display_name, avatar_path
  from profiles;

grant select on public_host_profiles to anon, authenticated;

create or replace view availability_public as
  select a.id, a.space_id, a.weekday, a.start_minute, a.end_minute
  from availability a
  join spaces s on s.id = a.space_id
  where s.status = 'active';

grant select on availability_public to anon, authenticated;

create or replace view space_media_public as
  select m.id, m.space_id, m.storage_path, m.kind, m.position
  from space_media m
  join spaces s on s.id = m.space_id
  where s.status = 'active';

grant select on space_media_public to anon, authenticated;

-- ==================================================================
-- Per-user views — security INVOKER, so the caller's row policies apply.
-- ==================================================================

-- Without security_invoker this aggregate would sum the entire ledger and
-- hand every practitioner's balance to whoever queried it.
create or replace view credit_balances
  with (security_invoker = true) as
  select practitioner_id, coalesce(sum(delta_cents), 0)::integer as balance_cents
  from credit_ledger
  group by practitioner_id;

grant select on credit_balances to authenticated;

-- access_code itself is never selected here. The reveal is a server-side
-- timer flipping access_code_revealed_at; the raw value must not round-trip
-- to a client that is not yet entitled to it, even into a field the UI
-- happens not to render.
create or replace view bookings_with_access_code
  with (security_invoker = true) as
  select
    b.id, b.space_id, b.practitioner_id, b.starts_at, b.ends_at, b.status,
    b.is_instant, b.was_pro, b.host_rate_cents, b.service_fee_cents,
    b.instant_fee_cents, b.pro_discount_cents, b.credit_applied_cents,
    b.total_cents, b.platform_cents, b.captured_at, b.cancelled_at,
    b.cancelled_by, b.access_code_revealed_at, b.created_at,
    case
      when b.practitioner_id = auth.uid() and b.access_code_revealed_at <= now()
        then b.access_code
      else null
    end as revealed_access_code
  from bookings b;

grant select on bookings_with_access_code to authenticated;

-- ==================================================================
-- Address reveal — a security definer function, not a view.
--
-- A practitioner has no row policy on `spaces`, so an invoker view would
-- return nothing to exactly the person entitled to the address. Granting
-- them a row policy instead would expose every other column on the row,
-- including the host's sublease document path. A definer function is the
-- narrow instrument: it runs the ownership check itself and returns only the
-- five fields needed to walk into the room.
-- ==================================================================

create or replace function space_access_details(p_space_id uuid)
returns table (
  address_line text,
  lat double precision,
  lng double precision,
  entry_instructions text,
  access_type access_type
)
language sql
stable
security definer
set search_path = public
as $$
  select s.address_line, s.lat, s.lng, s.entry_instructions, s.access_type
  from spaces s
  where s.id = p_space_id
    and exists (
      select 1 from bookings b
      where b.space_id = s.id
        and b.practitioner_id = auth.uid()
        and b.status in ('upcoming', 'completed')
    );
$$;

revoke all on function space_access_details(uuid) from public;
grant execute on function space_access_details(uuid) to authenticated;


-- ===================================================================
-- 0003_storage.sql
-- ===================================================================

-- Storage buckets
--
-- Three buckets, split by sensitivity rather than by feature, since that is
-- what the access policy actually depends on:
--
--   avatars        public read, one folder per user, owner-only write
--   space-media    public read (it's marketing content — photos/video of a
--                  room, never the address), host-only write on own space
--   verification-docs   private. Sublease proof, space insurance, and
--                  practitioner insurance certs. No in-app admin panel yet
--                  (the brief calls this out as deliberate, not an
--                  oversight), so review happens by staff through the
--                  Supabase dashboard with the service role — no client
--                  policy grants read access to anyone but the uploader.
--
-- Path convention: "{owner-scoped folder}/{filename}", so a single
-- storage.foldername(name) check can express "is this yours" without a
-- table join for avatars, and with one join for the space-scoped buckets.

insert into storage.buckets (id, name, public)
values
  ('avatars', 'avatars', true),
  ('space-media', 'space-media', true),
  ('verification-docs', 'verification-docs', false)
on conflict (id) do nothing;

-- Same reasoning as 0002: drop this file's own policies so it can be re-run.
-- Matched by name prefix rather than by table, because storage.objects carries
-- policies for every bucket in the project and dropping all of them would take
-- out ones this file never wrote.
do $$
declare existing record;
begin
  for existing in
    select policyname from pg_policies
    where schemaname = 'storage' and tablename = 'objects'
      and (
        policyname like 'avatars:%'
        or policyname like 'space-media:%'
        or policyname like 'verification-docs:%'
      )
  loop
    execute format('drop policy if exists %I on storage.objects', existing.policyname);
  end loop;
end $$;

-- ------------------------------------------------------------------
-- avatars — path: {user_id}/{filename}
-- ------------------------------------------------------------------

create policy "avatars: public read"
  on storage.objects for select
  using (bucket_id = 'avatars');

create policy "avatars: owner writes own folder"
  on storage.objects for insert
  with check (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "avatars: owner updates own folder"
  on storage.objects for update
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "avatars: owner deletes own folder"
  on storage.objects for delete
  using (
    bucket_id = 'avatars'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- ------------------------------------------------------------------
-- space-media — path: {space_id}/{filename}
-- ------------------------------------------------------------------

create policy "space-media: public read"
  on storage.objects for select
  using (bucket_id = 'space-media');

create policy "space-media: host writes own space's folder"
  on storage.objects for insert
  with check (
    bucket_id = 'space-media'
    and exists (
      select 1 from spaces s
      where s.id::text = (storage.foldername(name))[1]
        and s.host_id = auth.uid()
    )
  );

create policy "space-media: host deletes own space's folder"
  on storage.objects for delete
  using (
    bucket_id = 'space-media'
    and exists (
      select 1 from spaces s
      where s.id::text = (storage.foldername(name))[1]
        and s.host_id = auth.uid()
    )
  );

-- ------------------------------------------------------------------
-- verification-docs — no public read.
-- Paths: space/{space_id}/{filename}, practitioner/{user_id}/{filename}
-- ------------------------------------------------------------------

create policy "verification-docs: host reads own space's docs"
  on storage.objects for select
  using (
    bucket_id = 'verification-docs'
    and (storage.foldername(name))[1] = 'space'
    and exists (
      select 1 from spaces s
      where s.id::text = (storage.foldername(name))[2]
        and s.host_id = auth.uid()
    )
  );

create policy "verification-docs: host writes own space's docs"
  on storage.objects for insert
  with check (
    bucket_id = 'verification-docs'
    and (storage.foldername(name))[1] = 'space'
    and exists (
      select 1 from spaces s
      where s.id::text = (storage.foldername(name))[2]
        and s.host_id = auth.uid()
    )
  );

create policy "verification-docs: practitioner reads own docs"
  on storage.objects for select
  using (
    bucket_id = 'verification-docs'
    and (storage.foldername(name))[1] = 'practitioner'
    and (storage.foldername(name))[2] = auth.uid()::text
  );

create policy "verification-docs: practitioner writes own docs"
  on storage.objects for insert
  with check (
    bucket_id = 'verification-docs'
    and (storage.foldername(name))[1] = 'practitioner'
    and (storage.foldername(name))[2] = auth.uid()::text
  );


-- ===================================================================
-- 0004_narrow_public_profiles.sql
-- ===================================================================

-- Narrow public_host_profiles to actual hosts.
--
-- As first written it selected every row in `profiles`, so a practitioner's
-- display name and avatar were world-readable to any anonymous caller — the
-- view's name claimed a restriction its body never applied.
--
-- Only someone with a live listing needs a public identity: that is the name
-- attached to a room in Discover. A practitioner has no public presence in this
-- product at all.
--
-- Note for later: a host legitimately needs to see who booked their space, and
-- that is now deliberately not served here. It belongs in a security definer
-- function scoped to "practitioners holding a booking on a space you own",
-- alongside space_access_details, rather than in a world-readable view.

create or replace view public_host_profiles as
  select p.id, p.display_name, p.avatar_path
  from profiles p
  where exists (
    select 1
    from spaces s
    where s.host_id = p.id
      and s.status = 'active'
  );

grant select on public_host_profiles to anon, authenticated;


-- ===================================================================
-- 0005_host_bookings.sql
-- ===================================================================

-- Who booked my room?
--
-- 0004 narrowed public_host_profiles to actual hosts, which was right — a
-- practitioner has no public presence in this product — but it left a real gap:
-- a host must be able to see who is coming into their space, and that name now
-- lives behind RLS they cannot cross.
--
-- The answer is not to widen the public view back out. It is a function scoped
-- to exactly the relationship that justifies the access: you may see a
-- practitioner's name because they hold a booking on a space *you own*.
--
-- Note what it returns and what it does not. host_rate_cents is the host's net,
-- and no service fee, instant fee or platform figure appears anywhere in the
-- signature. The brief is explicit that hosts see earnings, never a percentage,
-- and leaving those columns out means a careless `select *` on the client
-- cannot leak them.

create or replace function host_bookings()
returns table (
  booking_id uuid,
  space_id uuid,
  starts_at timestamptz,
  ends_at timestamptz,
  status booking_status,
  net_cents integer,
  practitioner_name text,
  practitioner_avatar_path text
)
language sql
stable
security definer
set search_path = public
as $$
  select
    b.id,
    b.space_id,
    b.starts_at,
    b.ends_at,
    b.status,
    b.host_rate_cents,
    p.display_name,
    p.avatar_path
  from bookings b
  join spaces s on s.id = b.space_id
  join profiles p on p.id = b.practitioner_id
  where s.host_id = auth.uid()
  order by b.starts_at;
$$;

revoke all on function host_bookings() from public;
grant execute on function host_bookings() to authenticated;


-- ===================================================================
-- 0006_service_role_grants.sql
-- ===================================================================

-- Give service_role access to the tables the server actually writes.
--
-- This was missing, and the failure mode was thoroughly misleading: the secret
-- key authenticated fine — Storage answered 200 with it — while every REST call
-- came back denied. It read like a bad key. It was a missing GRANT.
--
-- The same lesson as 0002: BYPASSRLS lets a role ignore row policies, it does
-- not let it touch a table it has no privilege on. Stock Supabase hides this by
-- granting service_role everything through default privileges; with
-- auto-expose-new-tables off there are no defaults, so nothing is granted until
-- it is written down here.
--
-- Safe because the secret key never reaches a browser: src/lib/supabase/env.ts
-- throws if it is read client-side, and src/lib/stripe/client.ts and the server
-- helpers are marked server-only.
--
-- Full access rather than a narrow list, deliberately. service_role is the
-- trusted server identity that has to write a booking, its credit_ledger entry
-- and a Stripe PaymentIntent as one unit, and reconcile them from webhooks
-- afterwards. Trimming these grants would not add safety — anything holding
-- this key can already act as the platform — it would only produce a puzzling
-- 403 the next time a route needed a column nobody anticipated.

grant usage on schema public to service_role;

grant all privileges on table profiles to service_role;
grant all privileges on table spaces to service_role;
grant all privileges on table space_media to service_role;
grant all privileges on table availability to service_role;
grant all privileges on table bookings to service_role;
grant all privileges on table credit_ledger to service_role;

grant select on table spaces_public to service_role;
grant select on table public_host_profiles to service_role;
grant select on table availability_public to service_role;
grant select on table space_media_public to service_role;
grant select on table credit_balances to service_role;
grant select on table bookings_with_access_code to service_role;

grant execute on function space_access_details(uuid) to service_role;
grant execute on function host_bookings() to service_role;

-- Anything added later inherits these, so the next table does not repeat the
-- same debugging session.
alter default privileges in schema public
  grant all privileges on tables to service_role;
alter default privileges in schema public
  grant all privileges on sequences to service_role;


-- ===================================================================
-- 0007_space_details.sql
-- ===================================================================

-- Listing detail the wizard already collects but had nowhere to land:
-- amenities, a description, and the host's house rules.
--
-- `requirements` holds keys from the fixed vocabulary in src/lib/taxonomy.ts —
-- grip socks, no open flame, quiet building — rather than sentences. Keys can
-- be shown before booking, scanned at a glance and translated later; sentences
-- can only be read.
--
-- `house_rules` is the free-text overflow for the genuinely specific ("the cat
-- lives in the back room, please keep the door shut"). Deliberately secondary
-- to the structured list: anything common belongs in the vocabulary, where it
-- is visible and consistent across listings.
--
-- Both are on `spaces` and both are exposed through spaces_public, because a
-- rule discovered after paying is exactly the surprise this app refuses
-- everywhere else. They are requirements, not fine print.

alter table spaces
  add column if not exists description text not null default '',
  add column if not exists amenities text[] not null default '{}',
  add column if not exists requirements text[] not null default '{}',
  add column if not exists house_rules text not null default '';

-- Recreated rather than altered: a view does not pick up new columns on its
-- own, and Discover cannot show a rule it never selected.
create or replace view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, status, created_at,
    description, amenities, requirements, house_rules
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;
grant select on spaces_public to service_role;


-- ===================================================================
-- 0008_map_position.sql
-- ===================================================================

-- Where a listing sits on the illustrated browse map.
--
-- `lat`/`lng` already existed and stayed empty, because nothing geocoded an
-- address — the wizard collected a tap on a drawing. They are now filled from
-- the address the host picks, and they remain private: released only through
-- space_access_details, to someone who already holds a booking.
--
-- map_x / map_y are the separate, public question. The map on Discover is a
-- picture, not a locator, precisely because an address is private until it is
-- booked; putting real coordinates there would undo the rule the rest of the
-- schema spends its effort enforcing. So the browse position is derived from
-- the real one at an ~11 km granularity (see toBrowsePosition in src/lib/geo.ts)
-- and only that derived value is exposed.
--
-- Stored rather than computed in the view: the derivation would otherwise need
-- lat/lng in a view anon can select from, which is the leak this exists to
-- avoid.

alter table spaces
  add column if not exists map_x numeric(4,1) not null default 50,
  add column if not exists map_y numeric(4,1) not null default 50;

-- The illustration is 6..94 by 8..92 — a pin is drawn from its point upward,
-- so a value at the very edge would render half outside the frame.
do $$
begin
  alter table spaces add constraint spaces_map_position_in_frame
    check (map_x between 6 and 94 and map_y between 8 and 92);
exception
  when duplicate_object then null;
end $$;

create or replace view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, status, created_at,
    description, amenities, requirements, house_rules,
    map_x, map_y
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;
grant select on spaces_public to service_role;


-- ===================================================================
-- 0009_notifications.sql
-- ===================================================================

-- Transactional messages, and the queue that stops them going twice.
--
-- The problem this table exists for: sending is not transactional. A booking
-- is written to Postgres and an email is handed to Resend, and no transaction
-- spans both — the same shape as the Stripe call in booking-service.ts. So a
-- retried job, a redeployed function or a timeout that actually delivered can
-- all send the same message again, and "your session is cancelled" arriving
-- twice is not a cosmetic bug.
--
-- The fix is a unique key per (what, about what, over which channel), claimed
-- before the send. A second attempt collides and stops. Delivery is therefore
-- at-least-once rather than exactly-once — a send that succeeds and then dies
-- before it can be marked will go again — which is the right way round: a
-- duplicate door code is an annoyance, a missing one is someone locked out.
--
-- The message body is deliberately NOT stored. It is rendered from live data
-- at send time, so a retry carries current truth rather than a stale snapshot,
-- and no door code is ever copied into a second table.

alter table profiles
  -- E.164, so the country code is never ambiguous. Verified separately from
  -- being present: an unverified number is somebody's typo until proven
  -- otherwise, and texting a stranger's phone is worse than sending nothing.
  add column if not exists phone text,
  add column if not exists phone_verified_at timestamptz,
  add column if not exists notify_sms boolean not null default false;

do $$
begin
  alter table profiles add constraint profiles_phone_is_e164
    check (phone is null or phone ~ '^\+[1-9][0-9]{6,14}$');
exception
  when duplicate_object then null;
end $$;

do $$
begin
  create type notification_channel as enum ('email', 'sms');
exception
  when duplicate_object then null;
end $$;

create table if not exists notifications (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references profiles (id) on delete cascade,
  booking_id uuid references bookings (id) on delete cascade,
  kind text not null,
  channel notification_channel not null,

  -- The whole point of the table. Built by the caller as
  -- kind:subject-id:channel, so the same message about the same booking on the
  -- same channel can be claimed exactly once.
  dedupe_key text not null unique,

  attempts integer not null default 0,
  sent_at timestamptz,
  -- Set when a provider rejects in a way that will never succeed — a malformed
  -- address, an unreachable number. Distinct from "not sent yet" so a dead
  -- message stops being retried without pretending it was delivered.
  dropped_at timestamptz,
  last_error text,
  created_at timestamptz not null default now()
);

-- The queue's only hot query: what is still owed. Partial, because a delivered
-- notification is never looked up this way and there will be far more of those.
create index if not exists notifications_pending_idx
  on notifications (created_at)
  where sent_at is null and dropped_at is null;

create index if not exists notifications_user_idx on notifications (user_id, created_at desc);

-- ------------------------------------------------------------------
-- Access
--
-- Nobody reads this table from the client. It is written and read by the
-- service role alone, from the cron job and the booking paths — a practitioner
-- has no reason to enumerate what we have sent, and a host has less.
--
-- RLS on with no policy is the deliberate outcome: the base table denies
-- everyone, and the service role bypasses RLS entirely.
-- ------------------------------------------------------------------
alter table notifications enable row level security;

grant select, insert, update on notifications to service_role;


-- ===================================================================
-- 0010_verification_before_active.sql
-- ===================================================================

-- Move the sublease-proof requirement from "every row" to "every live listing".
--
-- sublease_doc_path was not-null, which reads like the right guarantee and is
-- not enforceable in the order the work actually happens. Storage policies for
-- the verification-docs bucket ask whether the first path segment is a space
-- this host owns, so a file cannot be uploaded until the space row exists —
-- and the row could not be inserted without the path. The only ways out were
-- to store a filename that pointed at nothing, which is what the app did and
-- left every listing unreviewable, or to write a placeholder, which is a lie
-- in a column that exists to prevent one.
--
-- The invariant worth keeping is not "no row without a document". It is "no
-- listing takes bookings without proof the host may sublet". That is what this
-- says, and it says it about exactly the moment it matters.

alter table spaces alter column sublease_doc_path drop not null;

do $$
begin
  alter table spaces add constraint spaces_active_needs_sublease_proof
    check (status <> 'active' or sublease_doc_path is not null);
exception
  when duplicate_object then null;
end $$;

-- Nothing existing can violate it: status defaults to 'pending' and only staff
-- move a listing to 'active', which is the review this constraint backs up.


-- ===================================================================
-- 0011_reviews_and_safety.sql
-- ===================================================================

-- Two-sided reviews, safety escalation, and emergency contacts.
--
-- Three things that only make sense together: a way for each side to say what
-- happened, a way for the bad ones to reach a person, and a way to reach
-- somebody if a session goes wrong while it is happening.
--
-- The rules themselves live in src/lib/reviews.ts and are tested there. What is
-- here is what the database must guarantee no matter what any client believes:
-- one review per side per booking, ratings inside 1..5, and a review that
-- cannot be written by anyone who was not in the room.

do $$
begin
  create type reviewer_role as enum ('practitioner', 'host');
exception
  when duplicate_object then null;
end $$;

do $$
begin
  create type escalation_priority as enum ('safety', 'urgent', 'review');
exception
  when duplicate_object then null;
end $$;

do $$
begin
  create type escalation_state as enum ('open', 'acknowledged', 'resolved');
exception
  when duplicate_object then null;
end $$;

-- ------------------------------------------------------------------
-- reviews
--
-- The sub-answers are nullable because the two roles ask different questions:
-- a practitioner is asked about access and cleanliness, a host about how the
-- room was left. Splitting into two tables would duplicate every rule about
-- visibility and escalation for the sake of a few empty columns.
-- ------------------------------------------------------------------
create table if not exists reviews (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references bookings (id) on delete cascade,
  -- Denormalised from the booking so a policy can check authorship without
  -- joining, and so a review survives as evidence of who wrote it.
  author_id uuid not null references profiles (id) on delete cascade,
  subject_id uuid not null references profiles (id) on delete cascade,
  role reviewer_role not null,

  overall smallint not null check (overall between 1 and 5),
  comment text not null default '',

  -- Ticked independently of the stars. A five-star session can still end with
  -- an unlocked fire door, and tying escalation only to a low rating loses
  -- exactly those reports.
  safety_concern boolean not null default false,

  -- Practitioner answers about the space.
  access_on_time boolean,
  cleanliness smallint check (cleanliness between 1 and 5),
  accuracy smallint check (accuracy between 1 and 5),
  would_book_again boolean,

  -- Host answers about the practitioner.
  left_as_found smallint check (left_as_found between 1 and 5),
  respected_house_rules boolean,
  on_time boolean,
  would_host_again boolean,

  created_at timestamptz not null default now(),

  -- One per side per booking. This is the constraint that makes the blind
  -- period meaningful: without it, a second review could be written after
  -- reading the counterpart.
  constraint reviews_one_per_side unique (booking_id, role),

  -- Nobody reviews themselves.
  constraint reviews_two_parties check (author_id <> subject_id)
);

create index if not exists reviews_subject_idx on reviews (subject_id, created_at desc);
create index if not exists reviews_booking_idx on reviews (booking_id);

-- ------------------------------------------------------------------
-- review_escalations
--
-- A separate row rather than a flag on the review, because what staff need to
-- track is the handling, not the rating: when it was seen, by whom, what was
-- decided. Written by the server when a qualifying review arrives.
-- ------------------------------------------------------------------
create table if not exists review_escalations (
  id uuid primary key default gen_random_uuid(),
  review_id uuid not null unique references reviews (id) on delete cascade,
  priority escalation_priority not null,
  state escalation_state not null default 'open',
  note text,
  created_at timestamptz not null default now(),
  acknowledged_at timestamptz,
  resolved_at timestamptz
);

create index if not exists review_escalations_open_idx
  on review_escalations (priority, created_at)
  where state <> 'resolved';

-- ------------------------------------------------------------------
-- Emergency contacts
--
-- Somebody to call if a session goes wrong while it is happening. Stored on
-- the profile and readable by nobody but the owner and staff — the counterpart
-- in a booking never sees it, in either direction. A practitioner alone in a
-- stranger's building and a host letting a stranger into theirs have the same
-- need and the same right to privacy about it.
-- ------------------------------------------------------------------
alter table profiles
  add column if not exists emergency_contact_name text,
  add column if not exists emergency_contact_phone text,
  add column if not exists emergency_contact_relationship text;

do $$
begin
  alter table profiles add constraint profiles_emergency_phone_is_e164
    check (emergency_contact_phone is null or emergency_contact_phone ~ '^\+[1-9][0-9]{6,14}$');
exception
  when duplicate_object then null;
end $$;

-- ------------------------------------------------------------------
-- Access
--
-- Reviews are written through a server route, never inserted from the client:
-- eligibility depends on the session having ended and on there being no
-- earlier review, and both are checks a client can be made to skip. So there
-- is no insert policy at all — the service role writes them.
--
-- Reading is the part clients do, and it is narrow: you may read a review you
-- wrote, and a review about you once it is visible. "Visible" is not a column
-- a client can be trusted to filter on, so it is computed here.
-- ------------------------------------------------------------------
alter table reviews enable row level security;
alter table review_escalations enable row level security;

-- Dropped by name and table together, so re-running this file replaces its own
-- policies rather than colliding with them.
do $$
declare existing record;
begin
  for existing in
    select policyname, tablename from pg_policies
    where schemaname = 'public' and tablename in ('reviews', 'review_escalations')
  loop
    execute format('drop policy if exists %I on public.%I', existing.policyname, existing.tablename);
  end loop;
end $$;

create policy "reviews: author reads own"
  on reviews for select
  using (author_id = auth.uid());

grant select on reviews to authenticated;
grant select, insert, update on reviews to service_role;
grant select, insert, update on review_escalations to service_role;

-- ------------------------------------------------------------------
-- public_reviews
--
-- What a listing shows. Security definer, and its safety is the column list:
-- the author's identity, the booking it came from and the safety flag are all
-- absent, so a host cannot work out which practitioner left three stars and
-- act on it.
--
-- Only released reviews appear. A review is released when its counterpart
-- exists, or when the blind period has run out — the same rule as
-- src/lib/reviews.ts, enforced here because this is the only copy a client
-- cannot bypass.
-- ------------------------------------------------------------------
/*
 * Dropped in dependency order: space_ratings reads from public_reviews, so
 * Postgres refuses to drop the second while the first exists. Re-running the
 * file is the ordinary case — apply.sql is pasted whole — and this failed on
 * every attempt after the first.
 */
drop view if exists space_ratings;
drop view if exists public_reviews;

create view public_reviews
with (security_invoker = false) as
  select
    r.id,
    r.subject_id,
    b.space_id,
    r.role,
    r.overall,
    r.comment,
    r.created_at
  from reviews r
  join bookings b on b.id = r.booking_id
  where
    exists (
      select 1 from reviews other
      where other.booking_id = r.booking_id and other.role <> r.role
    )
    or r.created_at + interval '14 days' <= now();

grant select on public_reviews to anon, authenticated;
grant select on public_reviews to service_role;

-- ------------------------------------------------------------------
-- space_ratings
--
-- The aggregate a listing card shows. Counted from released reviews only, so
-- a sealed one cannot be inferred by watching the number move.
--
-- The average is returned raw; the decision to withhold it under three
-- reviews belongs to src/lib/reviews.ts, which is where the reason for that
-- rule is written down.
-- ------------------------------------------------------------------
create view space_ratings
with (security_invoker = false) as
  select
    space_id,
    count(*)::int as review_count,
    avg(overall)::numeric(3, 2) as average_rating
  from public_reviews
  where role = 'practitioner'
  group by space_id;

grant select on space_ratings to anon, authenticated;
grant select on space_ratings to service_role;


-- ===================================================================
-- 0012_account_type.sql
-- ===================================================================

-- One account is one side of the marketplace, chosen once.
--
-- This reverses an earlier decision, so the reasoning is worth recording. The
-- brief said "you can switch anytime from the top of either screen", and the
-- schema had no role column on purpose: the same person could book a room on
-- Tuesday and let one on Wednesday.
--
-- In practice the two sides are not two moods of one person. A practitioner
-- does not acquire a leasable room by changing a setting, and a studio owner
-- browsing for somewhere to teach is a different business with different
-- paperwork, a different fee, a different payout arrangement and a different
-- insurance position. Showing both sets of controls to everyone made the app
-- ask each person to ignore half of it.
--
-- So: an account is one or the other, picked at sign-up, and not switchable
-- afterwards. Somebody who genuinely is both opens a second account, which is
-- the honest shape of "these are two businesses".

do $$
begin
  create type account_type as enum ('practitioner', 'host');
exception
  when duplicate_object then null;
end $$;

-- Nullable, because a profile row is created the moment someone signs in and
-- the choice happens on the screen after that. Null means "has not chosen
-- yet", which the app treats as the one screen it must show them.
alter table profiles add column if not exists account_type account_type;

-- ------------------------------------------------------------------
-- Making "cannot be changed" true rather than merely unoffered.
--
-- Hiding the control is not the rule; it is a description of the current UI.
-- A client holding a publishable key can PATCH any column its grant allows,
-- so without this a practitioner could make themselves a host with one
-- request — and skip the sublease proof, the legal acknowledgement and the
-- payout setup that being a host is supposed to require.
--
-- Null to a value is permitted: that is the one-time choice. Value to a
-- different value is refused. The service role is exempt so staff can fix a
-- genuine mistake, which is the difference between immutable and a trap.
-- ------------------------------------------------------------------
create or replace function profiles_account_type_is_final()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
begin
  if old.account_type is not null
     and new.account_type is distinct from old.account_type
     and current_user <> 'service_role'
  then
    raise exception 'account_type cannot be changed once it has been chosen'
      using errcode = 'check_violation';
  end if;

  return new;
end;
$$;

drop trigger if exists profiles_account_type_is_final on profiles;

create trigger profiles_account_type_is_final
  before update on profiles
  for each row
  execute function profiles_account_type_is_final();

-- ------------------------------------------------------------------
-- Listing a space requires being a host.
--
-- The trigger above stops the column changing; this stops it being
-- irrelevant. Without it, an account that never chose "host" could still
-- insert into spaces and the whole split would be decoration.
--
-- The existing policy is REPLACED rather than joined by a second one. Postgres
-- ORs permissive policies together, so adding "must be a host" beside "must be
-- your own row" would have meant either one passing — a restriction that
-- restricted nothing, and one that reads correct in a diff.
-- ------------------------------------------------------------------
drop policy if exists "spaces: host inserts own rows" on spaces;
drop policy if exists "spaces: only hosts may list" on spaces;

create policy "spaces: only hosts may list"
  on spaces for insert
  with check (
    host_id = auth.uid()
    and exists (
      select 1 from profiles p
      where p.id = auth.uid() and p.account_type = 'host'
    )
  );


-- ===================================================================
-- 0013_account_type_change_requests.sql
-- ===================================================================

-- Asking to move to the other side of the marketplace.
--
-- 0012 made account_type unchangeable by the client and left the service role
-- able to change it, which is the difference between a rule and a trap. This
-- is the front door to that exemption: somebody who picked wrong, or whose
-- circumstances genuinely changed, asks — and a person decides.
--
-- Deliberately not self-service. Becoming a host means sublease proof, a legal
-- acknowledgement and payout setup; becoming a practitioner means insurance.
-- A switch that skipped those would let an account acquire obligations it had
-- never satisfied, which is the whole reason the column is locked.

do $$
begin
  create type account_change_state as enum ('open', 'approved', 'declined');
exception
  when duplicate_object then null;
end $$;

create table if not exists account_type_change_requests (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references profiles (id) on delete cascade,

  -- Recorded rather than derived, so the record still reads correctly after
  -- the change has been applied and the profile no longer says what it was.
  current_type account_type not null,
  requested_type account_type not null,

  reason text not null default '',
  state account_change_state not null default 'open',

  created_at timestamptz not null default now(),
  decided_at timestamptz,
  decided_note text,

  constraint account_change_is_a_change check (current_type <> requested_type)
);

-- One open request per person. Without this, a refusal can be answered by
-- asking again immediately, and the queue becomes a way to apply pressure.
create unique index if not exists account_change_one_open_per_user
  on account_type_change_requests (user_id)
  where state = 'open';

create index if not exists account_change_open_idx
  on account_type_change_requests (created_at)
  where state = 'open';

-- ------------------------------------------------------------------
-- Access
--
-- Someone may read their own requests, so the app can show "we are looking at
-- this" rather than swallowing the ask. Writing goes through a server route —
-- the current_type on the row must be the profile's real one, and a client
-- that could set it could describe a change it is not actually making.
-- ------------------------------------------------------------------
alter table account_type_change_requests enable row level security;

do $$
declare existing record;
begin
  for existing in
    select policyname from pg_policies
    where schemaname = 'public' and tablename = 'account_type_change_requests'
  loop
    execute format('drop policy if exists %I on public.account_type_change_requests', existing.policyname);
  end loop;
end $$;

create policy "account changes: read own"
  on account_type_change_requests for select
  using (user_id = auth.uid());

grant select on account_type_change_requests to authenticated;
grant select, insert, update on account_type_change_requests to service_role;


-- ===================================================================
-- 0014_standing_points.sql
-- ===================================================================

-- Points, computed from what happened rather than stored.
--
-- There is no points column anywhere, on purpose. A stored balance can drift
-- from the events that produced it — a job that ran twice, a job that never
-- ran, a manual correction nobody wrote down — and once it has drifted there is
-- no way to settle an argument about it. This view recomputes from bookings and
-- reviews every time, so the number is always explainable: every point traces
-- to a session or a review somebody can be shown.
--
-- The scoring itself lives in src/lib/standing-points.ts and is tested there.
-- The constants are repeated here because SQL cannot import them, which is a
-- real duplication — standing_points.test.ts asserts they still agree.

drop view if exists standing_points;

create view standing_points
with (security_invoker = false) as
with
  -- A session counts only when money moved between two different people.
  -- Without the practitioner_id <> host_id check, a host with a second account
  -- books their own room and both sides collect, having paid only our fee.
  paid_sessions as (
    select
      b.practitioner_id,
      s.host_id,
      b.id as booking_id
    from bookings b
    join spaces s on s.id = b.space_id
    where b.status = 'completed'
      and b.captured_at is not null
      and b.practitioner_id <> s.host_id
  ),

  session_points as (
    select practitioner_id as user_id, count(*) * 15 as points from paid_sessions group by practitioner_id
    union all
    select host_id as user_id, count(*) * 15 as points from paid_sessions group by host_id
  ),

  -- Clean means nothing was raised against them on that session.
  clean_points as (
    select p.practitioner_id as user_id, count(*) * 2 as points
    from paid_sessions p
    where not exists (
      select 1 from reviews r
      where r.booking_id = p.booking_id and r.subject_id = p.practitioner_id and r.safety_concern
    )
    group by p.practitioner_id
    union all
    select p.host_id as user_id, count(*) * 2 as points
    from paid_sessions p
    where not exists (
      select 1 from reviews r
      where r.booking_id = p.booking_id and r.subject_id = p.host_id and r.safety_concern
    )
    group by p.host_id
  ),

  -- Stars on reviews *about* you, and only on sessions that counted — so a
  -- self-booked five stars is worth nothing either.
  review_points as (
    select r.subject_id as user_id, sum(r.overall) * 2 as points
    from reviews r
    join paid_sessions p on p.booking_id = r.booking_id
    group by r.subject_id
  ),

  -- Cancellations inside 24 hours, from whichever side did it.
  penalty_points as (
    select b.practitioner_id as user_id, count(*) * -25 as points
    from bookings b
    where b.status = 'cancelled_by_practitioner'
      and b.cancelled_at > b.starts_at - interval '24 hours'
    group by b.practitioner_id
    union all
    select s.host_id as user_id, count(*) * -25 as points
    from bookings b
    join spaces s on s.id = b.space_id
    where b.status = 'cancelled_by_host'
      and b.cancelled_at > b.starts_at - interval '24 hours'
    group by s.host_id
  ),

  -- An escalation that a person looked at and upheld. Open ones score nothing:
  -- a report is not a finding, and docking somebody before anybody has read it
  -- would make an accusation into a penalty.
  upheld_points as (
    select r.subject_id as user_id, count(*) * -100 as points
    from review_escalations e
    join reviews r on r.id = e.review_id
    where e.state = 'resolved' and e.note is not null
    group by r.subject_id
  )

select
  user_id,
  -- Floored at zero: a negative score keeps punishing after the punishment,
  -- and suspension is where repeated cancellation is actually handled.
  greatest(0, sum(points))::int as points
from (
  select * from session_points
  union all select * from clean_points
  union all select * from review_points
  union all select * from penalty_points
  union all select * from upheld_points
) all_points
group by user_id
/*
 * Your own row, and the filter is inside the view because it has to be.
 *
 * This is a security definer view, so it reads the base tables with the
 * owner's rights and no row policy applies — granting select without this
 * would hand every signed-in account everyone else's total. A points total is
 * not a vanity number: it is fifteen per paid session, so it divides straight
 * back into how many sessions somebody has had and, with a published rate,
 * roughly what they earned.
 *
 * auth.uid() is null for the service role, so staff read the base tables
 * directly rather than through here.
 */
having user_id = auth.uid();

grant select on standing_points to authenticated;


-- ===================================================================
-- 0015_messages.sql
-- ===================================================================

-- A thread per booking.
--
-- Scoped to a booking rather than to a pair of people, and that is the whole
-- privacy model. Two strangers have nothing to say to each other until one has
-- booked the other's room, and nothing to say afterwards once the record is
-- gone. A thread that outlived its booking would be a direct line between two
-- people who only ever agreed to share an hour.
--
-- Contact details are masked before the row is written, in
-- src/lib/message-redaction.ts. Both the sent text and the redacted text are
-- stored: the sender sees what they typed, everybody else sees what was sent.
-- Keeping the original matters when somebody reports harassment — the thing
-- that needs looking at is what was actually written.

create table if not exists messages (
  id uuid primary key default gen_random_uuid(),
  booking_id uuid not null references bookings (id) on delete cascade,
  sender_id uuid not null references profiles (id) on delete cascade,

  -- What the recipient sees.
  body text not null check (length(body) between 1 and 2000),

  /*
   * What the sender typed, when it differed.
   *
   * Null when nothing was masked, so the common case costs nothing. Readable
   * by staff alone — the point of masking is defeated if the recipient can
   * fetch the unmasked version, and the point of keeping it is defeated if
   * nobody can read it during a complaint.
   */
  original_body text,
  redacted_kinds text[] not null default '{}',

  created_at timestamptz not null default now(),
  read_at timestamptz
);

create index if not exists messages_booking_idx on messages (booking_id, created_at);
create index if not exists messages_unread_idx
  on messages (booking_id)
  where read_at is null;

-- ------------------------------------------------------------------
-- booking_participants
--
-- "Are you one of the two people on this booking" is asked by every policy
-- below, and getting it slightly different in each one is how the third
-- version ends up wrong. One function, one answer.
--
-- Definer, because a practitioner has no row policy on spaces and therefore
-- cannot see who hosts the room they booked.
-- ------------------------------------------------------------------
create or replace function is_booking_participant(p_booking_id uuid)
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1
    from bookings b
    join spaces s on s.id = b.space_id
    where b.id = p_booking_id
      and (b.practitioner_id = auth.uid() or s.host_id = auth.uid())
  );
$$;

-- ------------------------------------------------------------------
-- Access
--
-- Reading and writing are both allowed directly, unlike reviews. There is no
-- eligibility rule a client could skip: either you are on the booking or you
-- are not, and the function above settles it. What a client cannot be trusted
-- with is the masking, so inserts go through a server route that does it —
-- but the policy is the boundary, not the route.
-- ------------------------------------------------------------------
alter table messages enable row level security;

do $$
declare existing record;
begin
  for existing in
    select policyname from pg_policies
    where schemaname = 'public' and tablename = 'messages'
  loop
    execute format('drop policy if exists %I on public.messages', existing.policyname);
  end loop;
end $$;

create policy "messages: participants read the thread"
  on messages for select
  using (is_booking_participant(booking_id));

-- Marking as read is the only update a participant makes, and only on
-- somebody else's message — you do not mark your own as read.
create policy "messages: participants mark others' as read"
  on messages for update
  using (is_booking_participant(booking_id) and sender_id <> auth.uid())
  with check (is_booking_participant(booking_id) and sender_id <> auth.uid());

grant select, update on messages to authenticated;
grant select, insert, update on messages to service_role;

-- ------------------------------------------------------------------
-- messages_visible
--
-- What a participant reads. The column list is the point: original_body is
-- absent, so the unmasked text cannot be selected by the person the masking
-- was protecting somebody from.
--
-- Invoker, so the policy above still applies — this is a narrowing of rows the
-- caller may already reach, not a way around them.
-- ------------------------------------------------------------------
drop view if exists messages_visible;

create view messages_visible
with (security_invoker = true) as
  select
    id,
    booking_id,
    sender_id,
    body,
    redacted_kinds,
    created_at,
    read_at
  from messages;

grant select on messages_visible to authenticated;
grant select on messages_visible to service_role;


-- ===================================================================
-- 0016_session_counts.sql
-- ===================================================================

-- Sessions run, replacing the points view.
--
-- 0014 built `standing_points`: a weighted score over sessions, reviews and
-- cancellations, feeding tiers that granted a longer booking window, a waived
-- instant fee and a faster payout. All of it is gone, and the reasoning is
-- worth keeping rather than only the result.
--
-- Every one of those benefits was a rule that had to be explained, tested and
-- reasoned about at the moment somebody was trying to book a room — and none of
-- them made the marketplace work better. What replaces them is a count and
-- three badges at 100, 250 and 500. A badge changes no price and bends no rule,
-- so there is nothing to reconcile when it is wrong.
--
-- The one property carried over is the one that mattered: a session counts only
-- when money moved between two different people. Without it a host books their
-- own room, and a badge that can be manufactured in an afternoon is worth
-- nothing to somebody who spent a year earning one.

drop view if exists standing_points;
drop view if exists session_counts;

create view session_counts
with (security_invoker = false) as
with paid_sessions as (
  select b.practitioner_id, s.host_id
  from bookings b
  join spaces s on s.id = b.space_id
  where b.status = 'completed'
    and b.captured_at is not null
    and b.practitioner_id <> s.host_id
)
select user_id, count(*)::int as sessions
from (
  select practitioner_id as user_id from paid_sessions
  union all
  select host_id as user_id from paid_sessions
) both_sides
group by user_id
/*
 * Your own row, and the filter has to live inside the view.
 *
 * Security definer, so it reads the base tables with the owner's rights and no
 * row policy applies — granting select without this would hand every signed-in
 * account everyone else's session count, which for a host divides straight back
 * into roughly what they have earned.
 *
 * auth.uid() is null for the service role, so staff read the base tables
 * directly rather than through here.
 */
having user_id = auth.uid();

grant select on session_counts to authenticated;


-- ===================================================================
-- 0017_storage_paths_by_owner.sql
-- ===================================================================

-- Storage policies that do not ask another table a question.
--
-- Listing a space failed at the upload with "new row violates row-level
-- security policy", and every unit test passed, because the policy is not
-- code — it is four lines of SQL in a database, and nothing ran them.
--
-- What narrowed it: in the *same* bucket, as the *same* user, in the *same*
-- request shape, `practitioner/{uid}/file` uploaded fine and
-- `space/{space_id}/file` was refused. The only difference between those two
-- policies is that the second asks `exists (select 1 from spaces …)`. The row
-- was there — the host could select it through PostgREST a moment earlier —
-- and the subquery still did not find it from inside a storage policy.
--
-- Rather than keep a rule whose behaviour depends on where it is evaluated
-- from, the question is removed. A file is filed under the id of the person it
-- belongs to, and the policy compares that to auth.uid() — the same shape as
-- the avatars and practitioner policies, both of which have always worked.
--
--   space-media          {host_id}/{space_id}/{file}
--   verification-docs    space/{host_id}/{space_id}/{file}
--
-- Three things get better, quite apart from uploads working:
--
--   * It stops depending on the `spaces` select policy. A future change there
--     could silently take uploads with it, and the failure would appear in a
--     completely unrelated part of the app.
--   * It removes the ordering. Files no longer have to wait for the row to
--     exist, so the create-row-then-delete-it-if-the-upload-fails dance is no
--     longer load-bearing.
--   * The space id stays in the path, so a listing's files are still grouped
--     and still deletable as one prefix.
--
-- What it gives up: the policy no longer proves the space belongs to the host,
-- only that the folder does. A host could file a document under a space id
-- that is not theirs — inside their own folder, readable only by them, and
-- reachable from nothing, since every read starts from a space row and its
-- recorded path. It buys nothing and exposes nothing.
--
-- Safe to apply as-is: all three buckets are empty, so there are no files to
-- move. If that stops being true, move the objects first — the policies below
-- will refuse the old paths.

do $$
declare existing record;
begin
  for existing in
    select policyname from pg_policies
    where schemaname = 'storage' and tablename = 'objects'
      and (policyname like 'space-media:%' or policyname like 'verification-docs: host%')
  loop
    execute format('drop policy if exists %I on storage.objects', existing.policyname);
  end loop;
end $$;

-- ------------------------------------------------------------------
-- space-media — {host_id}/{space_id}/{file}
--
-- Public read, as before: these are photos of a room, never an address.
-- ------------------------------------------------------------------

create policy "space-media: public read"
  on storage.objects for select
  using (bucket_id = 'space-media');

create policy "space-media: host writes own folder"
  on storage.objects for insert
  with check (
    bucket_id = 'space-media'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "space-media: host updates own folder"
  on storage.objects for update
  using (
    bucket_id = 'space-media'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

create policy "space-media: host deletes own folder"
  on storage.objects for delete
  using (
    bucket_id = 'space-media'
    and (storage.foldername(name))[1] = auth.uid()::text
  );

-- ------------------------------------------------------------------
-- verification-docs — space/{host_id}/{space_id}/{file}
--
-- Still no public read, and still no policy granting anyone but the uploader
-- sight of it. Staff read these with the secret key through the admin route,
-- which signs one URL for one path after checking the session.
-- ------------------------------------------------------------------

create policy "verification-docs: host reads own space docs"
  on storage.objects for select
  using (
    bucket_id = 'verification-docs'
    and (storage.foldername(name))[1] = 'space'
    and (storage.foldername(name))[2] = auth.uid()::text
  );

create policy "verification-docs: host writes own space docs"
  on storage.objects for insert
  with check (
    bucket_id = 'verification-docs'
    and (storage.foldername(name))[1] = 'space'
    and (storage.foldername(name))[2] = auth.uid()::text
  );

create policy "verification-docs: host deletes own space docs"
  on storage.objects for delete
  using (
    bucket_id = 'verification-docs'
    and (storage.foldername(name))[1] = 'space'
    and (storage.foldername(name))[2] = auth.uid()::text
  );


-- ===================================================================
-- 0018_document_review.sql
-- ===================================================================

-- What happened to the file a host uploaded.
--
-- A host hands over their lease — the document that proves they are allowed to
-- sublet at all — and then the app goes quiet. The listing says "pending", and
-- pending covers everything: not looked at yet, looked at and fine, looked at
-- and unreadable. There was no way to tell which, and no way to find out
-- except to wait and see whether the listing went live.
--
-- That is the wrong side of the asymmetry. We are holding somebody's lease and
-- their insurance certificate, and they are the one who cannot see what became
-- of it.
--
-- Recorded per document rather than per listing, because the two do not move
-- together: insurance is optional and can be missing while the sublease is
-- fine, and a rejected insurance certificate should not read as a rejected
-- listing.

do $$ begin
  create type doc_review_state as enum ('pending', 'verified', 'rejected');
exception when duplicate_object then null;
end $$;

alter table spaces
  add column if not exists sublease_doc_state doc_review_state not null default 'pending',
  add column if not exists sublease_doc_reviewed_at timestamptz,
  add column if not exists insurance_doc_state doc_review_state not null default 'pending',
  add column if not exists insurance_doc_reviewed_at timestamptz,
  -- Shown to the host verbatim when something is rejected. Written by staff,
  -- so a rejection can say "the second page is cut off" rather than "rejected".
  add column if not exists doc_review_note text;

-- ------------------------------------------------------------------
-- A state and a timestamp that cannot disagree.
--
-- "Verified" with no date is a claim with nothing behind it, and a date on
-- something still pending is a review that did not happen. Either both or
-- neither, enforced here rather than remembered at each call site.
-- ------------------------------------------------------------------
alter table spaces
  drop constraint if exists spaces_sublease_review_consistent;
alter table spaces
  add constraint spaces_sublease_review_consistent check (
    (sublease_doc_state = 'pending') = (sublease_doc_reviewed_at is null)
  );

alter table spaces
  drop constraint if exists spaces_insurance_review_consistent;
alter table spaces
  add constraint spaces_insurance_review_consistent check (
    (insurance_doc_state = 'pending') = (insurance_doc_reviewed_at is null)
  );

-- ------------------------------------------------------------------
-- Existing listings, recorded before the rule is imposed.
--
-- The constraint below used to sit above this block, and adding a check
-- validates every row already in the table — so it was judging listings that
-- were live and correct against a column that had only just been created and
-- still said 'pending' for all of them. It failed on the first real database
-- it met, having passed every test, because the test database had no rows in
-- it yet.
--
-- Anything already live was reviewed by a person before it was switched on,
-- so it is recorded as verified rather than dropped back into a queue that
-- would ask them to prove it twice. Pending ones stay pending, which is what
-- they are.
-- ------------------------------------------------------------------
update spaces
set sublease_doc_state = 'verified',
    sublease_doc_reviewed_at = coalesce(updated_at, created_at)
where status = 'active'
  and sublease_doc_state = 'pending';

update spaces
set insurance_doc_state = 'verified',
    insurance_doc_reviewed_at = coalesce(updated_at, created_at)
where status = 'active'
  and insurance_doc_path is not null
  and insurance_doc_state = 'pending';

-- ------------------------------------------------------------------
-- A live listing has a verified lease behind it.
--
-- 0010 already refuses an active listing with no sublease document. This is
-- the same rule one step further on: having the file is not the same as
-- having read it, and "active" is the app telling practitioners this room is
-- legitimately available.
-- ------------------------------------------------------------------
alter table spaces
  drop constraint if exists spaces_active_requires_verified_lease;
alter table spaces
  add constraint spaces_active_requires_verified_lease check (
    status <> 'active' or sublease_doc_state = 'verified'
  );


-- ===================================================================
-- 0019_edit_listing.sql
-- ===================================================================

-- Editing a listing, and what a host may change on their own.
--
-- Until now a listing could not be edited at all. The rate was wrong, or the
-- entry instructions changed, and the only route was to delist and start
-- again — which loses the reviews and the history along with the mistake.
--
-- The rule underneath all of this is one sentence: **a change must never
-- rewrite something somebody has already agreed to.** Everything below is that
-- sentence applied to a particular column.
--
--   Free to change, live immediately
--     name, entry instructions, capacity, turnover buffer, accessibility,
--     restroom, photos. None of these is what a practitioner booked; they
--     describe the room they are walking into, and a host correcting them is
--     the app working.
--
--   Free to change, future bookings only
--     the hourly rate. Bookings freeze their own money at creation, so a rate
--     change cannot reach one that exists. A practitioner who booked at $45
--     pays $45 whatever happens next.
--
--   Sends the listing back for review
--     the address, the room type, or a replaced sublease document. We verified
--     a specific lease for a specific address; changing either means what we
--     checked is not what is listed. It goes back to pending and off search
--     until somebody has looked again.
--
--   Refused outright while sessions are booked
--     the address and the room type. Not "re-reviewed" — refused. Somebody
--     has arranged their day around a room at that address, and moving it
--     underneath them is the exact harm the cancellation policy exists to
--     prevent, done quietly instead of with a notification. A host who has
--     genuinely moved cancels those sessions first, which is visible, counts
--     against their standing, and tells the practitioner.
--
-- Enforced by a trigger, because "the client will only send the right fields"
-- is not a rule, it is a hope.

create or replace function enforce_listing_edit_rules()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  moved boolean;
  booked integer;
begin
  moved := new.address_line is distinct from old.address_line
        or new.category is distinct from old.category
        or new.lat is distinct from old.lat
        or new.lng is distinct from old.lng;

  if moved then
    select count(*) into booked
    from bookings
    where space_id = old.id
      and status = 'upcoming'
      and starts_at > now();

    if booked > 0 then
      raise exception
        'This space has % upcoming %. Its address and room type cannot change until those sessions are done or cancelled.',
        booked, case when booked = 1 then 'session' else 'sessions' end
        using errcode = 'check_violation';
    end if;
  end if;

  /*
   * Back to pending, and the review state with it.
   *
   * Leaving the document verified while the address changes underneath it is
   * how a listing ends up live with a lease for somewhere else — the exact
   * thing the constraint in 0018 exists to make impossible, defeated by an
   * update that never touched the document column.
   */
  if moved or new.sublease_doc_path is distinct from old.sublease_doc_path then
    new.status := 'pending';
    new.sublease_doc_state := 'pending';
    new.sublease_doc_reviewed_at := null;
    new.doc_review_note := null;
  end if;

  if new.insurance_doc_path is distinct from old.insurance_doc_path then
    new.insurance_doc_state := 'pending';
    new.insurance_doc_reviewed_at := null;
  end if;

  new.updated_at := now();
  return new;
end;
$$;

drop trigger if exists spaces_edit_rules on spaces;

/*
 * Only when a host is doing the editing.
 *
 * Staff approving a listing is an update too, and running these rules over it
 * would put the row straight back to pending the moment it was approved. The
 * service role has no auth.uid(), which is what separates the two.
 */
create trigger spaces_edit_rules
  before update on spaces
  for each row
  when (auth.uid() is not null)
  execute function enforce_listing_edit_rules();

-- ------------------------------------------------------------------
-- The columns a host may write at all.
--
-- The trigger decides what a change costs; this decides what is a change.
-- Status is absent on purpose — a host cannot approve their own listing, and
-- taking one down is a separate, deliberate action rather than a field on an
-- edit form.
-- ------------------------------------------------------------------
revoke update on spaces from authenticated;

grant update (
  name,
  category,
  hourly_rate_cents,
  capacity,
  access_type,
  entry_instructions,
  address_line,
  lat,
  lng,
  accessible,
  restroom,
  buffer_minutes,
  sublease_doc_path,
  insurance_doc_path,
  updated_at
) on spaces to authenticated;


-- ===================================================================
-- 0020_terms_acceptance.sql
-- ===================================================================

-- Who agreed to what, and when.
--
-- The terms existed and nobody had accepted them. A host acknowledged
-- something per listing — `spaces.legal_ack_at`, which covers the sublease
-- declaration for that one room — and a practitioner accepted nothing at all.
-- So the rule that matters most commercially, that a session arranged off the
-- app is between the two people who arranged it, was written down where
-- neither of them had ever agreed to it.
--
-- "It was in the terms" is worth little without a record of the moment it was
-- shown and taken. This is that record: one row per account, the version they
-- accepted, and the time.
--
-- Versioned rather than a boolean, because the terms will change. A boolean
-- says somebody once agreed to something; a version says what. When the text
-- changes materially the constant in the app moves, and everyone is asked
-- again — which is the only honest way to keep the record true.

alter table profiles
  add column if not exists terms_accepted_at timestamptz,
  add column if not exists terms_version integer;

-- Both or neither. A version with no timestamp is a claim with no moment
-- behind it, and a timestamp with no version is a moment with no text.
alter table profiles
  drop constraint if exists profiles_terms_consistent;
alter table profiles
  add constraint profiles_terms_consistent check (
    (terms_accepted_at is null) = (terms_version is null)
  );

-- ------------------------------------------------------------------
-- Write-once per version, and never backdated.
--
-- Acceptance is a fact about a past moment. A client that could set the
-- timestamp would be able to say somebody agreed last year, and one that could
-- lower the version would be able to un-accept a change they had already been
-- shown. Both are decided here rather than trusted to the caller.
-- ------------------------------------------------------------------
create or replace function enforce_terms_acceptance()
returns trigger
language plpgsql
security definer
set search_path = public
as $$
declare
  was integer := case when tg_op = 'UPDATE' then old.terms_version else null end;
begin
  /*
   * Insert as well as update, because the client upserts.
   *
   * The app writes a profile with `on conflict do update`, and Postgres checks
   * the proposed tuple before the conflict is resolved. A trigger that only
   * fired on UPDATE therefore never ran: the version arrived without a
   * timestamp, and the constraint below — the one insisting the two agree —
   * rejected it. Both paths, so acceptance is recorded however it arrives.
   */
  if new.terms_version is distinct from was
     or (tg_op = 'UPDATE' and new.terms_accepted_at is distinct from old.terms_accepted_at) then

    if new.terms_version is null then
      if was is null then
        return new;
      end if;
      raise exception 'Accepted terms cannot be withdrawn.'
        using errcode = 'check_violation';
    end if;

    if was is not null and new.terms_version < was then
      raise exception 'Terms version cannot go backwards.'
        using errcode = 'check_violation';
    end if;

    -- The clock is the server's, whatever the client sent.
    new.terms_accepted_at := now();
  end if;

  return new;
end;
$$;

drop trigger if exists profiles_terms_acceptance on profiles;

create trigger profiles_terms_acceptance
  before insert or update on profiles
  for each row
  when (auth.uid() is not null)
  execute function enforce_terms_acceptance();

-- ------------------------------------------------------------------
-- Existing accounts.
--
-- Left null on purpose. Backfilling would record an acceptance that never
-- happened, which is worse than having none — it is the one field whose whole
-- value is that it is true. They are asked next time they open the app.
-- ------------------------------------------------------------------


-- ===================================================================
-- 0021_emergency_phone_free_text.sql
-- ===================================================================

-- An emergency contact number is whatever the person wrote down.
--
-- The column insisted on E.164: a leading plus, a country code, no spaces.
-- The reasoning was that a number nobody can dial is no use in a hurry, which
-- is true and led to the wrong rule. What it produced was a field that
-- rejected "0533 395 5823", "(415) 555-0134" and "555 0134 ext. 2" — every
-- one of which a person on our team could dial, and every one of which is how
-- somebody actually writes their partner's number.
--
-- A validator that refuses the real answer does not get a better answer. It
-- gets an empty field, and an empty field in an emergency is the outcome this
-- was supposed to prevent.
--
-- So it is text. It is read by a person, not dialled by a machine. The only
-- limit kept is a length, which stops the column being used as free storage.

alter table profiles
  drop constraint if exists profiles_emergency_phone_is_e164;

do $$
begin
  alter table profiles add constraint profiles_emergency_phone_length
    check (
      emergency_contact_phone is null
      or length(btrim(emergency_contact_phone)) between 4 and 40
    );
exception
  when duplicate_object then null;
end $$;


-- ===================================================================
-- 0022_public_area.sql
-- ===================================================================

-- Which part of town, without which door.
--
-- The public view carried no location at all: no address, no coordinates, no
-- city. A practitioner browsing saw a room called "GamePlay", the word
-- "nearby", and nothing else — and "nearby" is computed from a location they
-- may not have shared, so often it said nothing whatsoever.
--
-- Withholding the street address is right and stays. It protects a host
-- letting a stranger into their building, and it is what stops somebody
-- looking the studio up and booking around us.
--
-- Withholding the town is a different thing, and it was not a decision so much
-- as the same rule applied one level too far. Nobody books an hour in a room
-- they cannot place. Asking somebody to commit their card, their afternoon and
-- their own client to a location they will not be told until afterwards is not
-- privacy, it is a room nobody books.
--
-- So: the first comma-separated segment is dropped and the rest kept.
--
--   stored   1840 Gateway Dr, San Mateo, CA 94404, USA
--   shown    San Mateo, CA 94404, USA
--
-- Google's formatted addresses lead with the street line, which is what makes
-- this reliable. When there is no comma there is no way to tell a street from
-- a town, so nothing is shown rather than guessed — a wrong guess here leaks
-- the address, and the whole point is that it cannot.
--
-- Computed in the view rather than in the client. A column the browser has to
-- be trusted to trim is a column the browser has already been sent.

create or replace function public_area(address text)
returns text
language sql
immutable
parallel safe
as $$
  select case
    when address is null then null
    when position(',' in address) = 0 then null
    else btrim(substring(address from position(',' in address) + 1))
  end;
$$;

-- Dropped rather than replaced.
--
-- `create or replace view` cannot remove a column, so once a later migration
-- has widened this view, re-running this one fails: it tries to go back to
-- fewer columns. Migrations are applied more than once in this project — the
-- whole file is pasted into a SQL editor — so every one of them has to survive
-- meeting a database that is already ahead of it.
--
-- Nothing selects from this view, so there is nothing to cascade to.
drop view if exists spaces_public;

create view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, status, created_at,
    description, amenities, requirements, house_rules,
    map_x, map_y,
    public_area(address_line) as area
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;
grant select on spaces_public to service_role;


-- ===================================================================
-- 0023_approximate_location.sql
-- ===================================================================

-- Roughly where, so a map can be a map.
--
-- The browse map was a hand-drawn SVG: painted roads, painted parks, and pins
-- placed by `map_x`/`map_y` — two decorative numbers from the prototype that
-- correspond to nothing. It looked like a map, so somebody reading it believed
-- they were being told where a room is. They were not.
--
-- The reason it was a drawing is sound and does not change: a listing's exact
-- position is private until it has been booked, and plotting the real point
-- would hand every address to anybody who opened the app.
--
-- What this adds is the middle that most marketplaces settle on. Each listing
-- gets a point offset by a few hundred metres, computed here and exposed
-- instead of the real one. A practitioner can see which part of town a room is
-- in and how far it is; nobody can see which building.
--
-- Two properties make the offset safe:
--
--   Deterministic. Derived from the listing id, so it does not move between
--   requests. A point that jitters on every refresh can be averaged back to
--   the true position by asking repeatedly, which would defeat the whole
--   thing.
--
--   Computed in the view. The real coordinates never enter the response, so
--   there is no client that could be trusted incorrectly and no field that
--   might be read by something we did not write.

-- An angle and a distance, rather than a random point in a square.
--
-- Offsetting each axis independently seemed fine and was not: measured over
-- two hundred listings the displacement ranged from 42m to 547m, and one in
-- fourteen landed under 100m. A published point 42m from the door is not a
-- neighbourhood, it is the building.
--
-- Picking a direction and a distance instead puts every listing in a band —
-- never nearer than MIN, never further than MAX — so there is no listing whose
-- approximate position is nearly its real one.
create or replace function approx_offset_metres(seed uuid)
returns double precision
language sql
immutable
parallel safe
as $$
  -- 250m to 450m. Far enough that the point is not the address; close enough
  -- that "twenty minutes away" is still true.
  select 250 + (abs(hashtext(seed::text || ':distance')) % 201);
$$;

create or replace function approx_bearing_radians(seed uuid)
returns double precision
language sql
immutable
parallel safe
as $$
  /*
   * Stable for a given listing, which is the property that matters. A point
   * that moved between requests could be averaged back to the true position
   * by asking repeatedly, which would defeat all of this.
   */
  select radians((abs(hashtext(seed::text || ':bearing')) % 360)::double precision);
$$;

create or replace function approx_lat(id uuid, lat double precision)
returns double precision
language sql
immutable
parallel safe
as $$
  select case when lat is null then null
    else round(
      (lat + (approx_offset_metres(id) * cos(approx_bearing_radians(id))) / 111320.0)::numeric,
      5
    )::double precision
  end;
$$;

create or replace function approx_lng(id uuid, lat double precision, lng double precision)
returns double precision
language sql
immutable
parallel safe
as $$
  select case when lng is null or lat is null then null
    /*
     * Longitude degrees narrow towards the poles, so the same distance is a
     * wider angle further north. Without the cosine the offset would collapse
     * to nothing in Reykjavik and be correct only at the equator.
     */
    else round(
      (
        lng
        + (approx_offset_metres(id) * sin(approx_bearing_radians(id)))
          / (111320.0 * greatest(cos(radians(lat)), 0.01))
      )::numeric,
      5
    )::double precision
  end;
$$;

-- Dropped rather than replaced, for the same reason as 0022: a re-run must
-- not fail against a database that already has the wider view.
drop view if exists spaces_public;

create view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, status, created_at,
    description, amenities, requirements, house_rules,
    map_x, map_y,
    public_area(address_line) as area,
    approx_lat(id, lat) as approx_lat,
    approx_lng(id, lat, lng) as approx_lng
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;
grant select on spaces_public to service_role;


-- ===================================================================
-- 0024_saved_postcode.sql
-- ===================================================================

-- A postcode somebody typed, kept until they change it.
--
-- Location has been per-visit until now, and for GPS that is the right
-- default: a coordinate is where a person physically is, we need it once to
-- sort a list, and keeping it would be building a record of somebody's
-- movements to save them a tap.
--
-- A postcode they typed is not that. It is a preference — "sort by what's near
-- my studio" — and asking for it every time is not privacy, it is friction
-- with nothing on the other side of it. Coarse enough to be a district rather
-- than an address, given deliberately, and changeable in one place.
--
-- The GPS path is unchanged and still forgets. Only what somebody wrote down
-- is remembered.

alter table profiles
  add column if not exists search_postcode text;

-- Long enough for anywhere that has postcodes, short enough that the column
-- cannot become a notes field.
alter table profiles
  drop constraint if exists profiles_search_postcode_length;
alter table profiles
  add constraint profiles_search_postcode_length check (
    search_postcode is null or length(btrim(search_postcode)) between 3 and 12
  );

-- ------------------------------------------------------------------
-- Writable by its owner, like the rest of the row.
--
-- 0019 revoked the blanket update on `spaces` and re-granted per column; the
-- profiles grant was never narrowed that way, so this needs nothing beyond the
-- policy that already restricts a profile to its owner.
-- ------------------------------------------------------------------


-- ===================================================================
-- 0025_notification_history.sql
-- ===================================================================

-- What we sent you, where you can find it.
--
-- The app has been sending email since the first booking and keeping no
-- record anybody could read. A host who missed the message about a session
-- starting in an hour had nowhere to look — not a stale inbox, not a spam
-- folder, nothing inside the product that could tell them it had been sent at
-- all. The row existed the whole time; only staff could see it.
--
-- Exposed through a view rather than a policy on the table, because most of
-- what the table holds is an operator's business and not the recipient's:
--
--   dedupe_key   an internal claim token
--   attempts     how hard the queue tried
--   last_error   a provider's words, written for us
--   dropped_at   that we gave up
--
-- None of that helps somebody asking "did the door code come through". What
-- does help is what it was about, when it was sent, and — plainly — when it
-- was not.

create or replace view my_notifications
with (security_invoker = true) as
  select
    id,
    booking_id,
    kind,
    channel,
    sent_at,
    created_at,
    /*
     * Three states, and the third is the one this exists for.
     *
     * "Sent" and "queued" are both fine. "Failed" is the answer somebody is
     * actually looking for when they are standing outside a door, and the app
     * has never been able to give it.
     */
    case
      when sent_at is not null then 'sent'
      when dropped_at is not null then 'failed'
      else 'queued'
    end as state
  from notifications
  where user_id = auth.uid();

grant select on my_notifications to authenticated;

-- ------------------------------------------------------------------
-- The row policy the view leans on.
--
-- security_invoker means this runs with the caller's rights, so `notifications`
-- needs a policy of its own or the view returns nothing. Select only: nobody
-- may write their own notification history, and it is scoped to the recipient
-- rather than to a booking — a host and a practitioner on the same booking get
-- different messages, and each sees theirs.
-- ------------------------------------------------------------------
drop policy if exists "notifications: read your own" on notifications;

create policy "notifications: read your own"
  on notifications for select
  using (user_id = auth.uid());

/*
 * Column by column, not the whole row.
 *
 * A blanket `grant select on notifications` would have made the view
 * decorative: the policy lets somebody read their own rows, so they could
 * simply query the table and get last_error, attempts and dedupe_key —
 * every field the view was written to keep back. The grant is the boundary;
 * the view is the presentation.
 *
 * dropped_at is here because the view derives 'failed' from it, and a
 * security_invoker view can only read what the caller may read.
 */
grant select (id, user_id, booking_id, kind, channel, sent_at, dropped_at, created_at)
  on notifications to authenticated;


-- ===================================================================
-- 0026_access_details.sql
-- ===================================================================

-- What "accessible" actually means for this room.
--
-- The column was a boolean, and the screen rendered it as a chip reading
-- "Wheelchair accessible". A wheelchair user cannot act on that. Is there a
-- step at the front door? Is the lift wide enough to turn in? Is the restroom
-- one they can use? The chip answers none of it while looking like an answer,
-- so somebody books, travels, pays, arrives with their own client waiting, and
-- cannot get in.
--
-- A boolean also invites the wrong answer honestly given. A host with one
-- shallow step at the entrance genuinely does not know which box to tick, and
-- most will tick yes because the room itself is fine.
--
-- So: four facts, each one an obstacle somebody is actually stopped by.
-- Structured rather than free text, because free text produces "yes, fully
-- accessible!" — the same claim with more words.
--
-- Null throughout means not answered, which is shown as not answered. An
-- unanswered question is more use than a guess, since a practitioner can ask.

do $$ begin
  create type entrance_access as enum ('step_free', 'one_step', 'steps');
exception when duplicate_object then null;
end $$;

do $$ begin
  create type lift_access as enum ('ground_floor', 'lift', 'stairs_only');
exception when duplicate_object then null;
end $$;

do $$ begin
  create type restroom_access as enum ('accessible', 'standard', 'none');
exception when duplicate_object then null;
end $$;

alter table spaces
  -- Getting from the pavement to the door.
  add column if not exists entrance_access entrance_access,
  -- Getting from the door to the room.
  add column if not exists floor_access lift_access,
  -- The measurement that decides it, in inches. Null when not measured.
  add column if not exists doorway_inches integer,
  add column if not exists restroom_access restroom_access;

alter table spaces
  drop constraint if exists spaces_doorway_plausible;
alter table spaces
  add constraint spaces_doorway_plausible check (
    doorway_inches is null or doorway_inches between 18 and 96
  );

-- ------------------------------------------------------------------
-- Published, because this is what somebody decides on.
--
-- None of it locates the room — a doorway width is not an address — so it
-- belongs in the public view alongside capacity and the room type rather than
-- behind the booking.
-- ------------------------------------------------------------------
drop view if exists spaces_public;

create view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, status, created_at,
    description, amenities, requirements, house_rules,
    map_x, map_y,
    entrance_access, floor_access, doorway_inches, restroom_access,
    public_area(address_line) as area,
    approx_lat(id, lat) as approx_lat,
    approx_lng(id, lat, lng) as approx_lng
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;
grant select on spaces_public to service_role;

-- The host may answer them, like the rest of their listing. 0019 revoked the
-- blanket update and grants per column, so these need adding to that list.
grant update (entrance_access, floor_access, doorway_inches, restroom_access)
  on spaces to authenticated;

-- ------------------------------------------------------------------
-- The old boolean.
--
-- Left in place and left alone. Migrating it would mean inventing answers —
-- "accessible = true" says nothing about which of the four is true — and a
-- fabricated accessibility claim is worse than a missing one. Existing
-- listings show as unanswered until a host answers.
-- ------------------------------------------------------------------


-- ===================================================================
-- 0027_address_at_commitment.sql
-- ===================================================================

-- The address arrives when the booking becomes committed.
--
-- It used to arrive the moment a booking existed. That left a hole with no
-- cost attached to it: book a room, read the address, cancel more than 24
-- hours out, and the authorisation is voided in full. Nothing charged, nothing
-- counted against standing, and the exact address of somebody's studio
-- collected for free. Repeat for every listing on the board.
--
-- The 24-hour line already marks the moment a booking stops being free to walk
-- away from — cancel inside it and the full amount is captured. So that is the
-- moment the address is worth its cost, and it is the same boundary the refund
-- policy and the standing rules use. One line, three consequences, nothing new
-- to explain.
--
-- A booking made inside the window is committed from the start, so it reveals
-- immediately. Nobody waits for a line they are already past.
--
-- What does not change: the area was always public, so a practitioner has
-- known roughly where the room is since before they booked. This withholds the
-- doorway, not the neighbourhood.

create or replace function space_access_details(p_space_id uuid)
returns table (
  address_line text,
  lat double precision,
  lng double precision,
  entry_instructions text,
  access_type access_type
)
language sql
stable
security definer
set search_path = public
as $$
  select s.address_line, s.lat, s.lng, s.entry_instructions, s.access_type
  from spaces s
  where s.id = p_space_id
    and exists (
      select 1 from bookings b
      where b.space_id = s.id
        and b.practitioner_id = auth.uid()
        and b.status in ('upcoming', 'completed')
        /*
         * Inside the free-cancellation window, or already past.
         *
         * `starts_at - now() < 24h` covers both: a session tomorrow morning,
         * and one that happened last week. A completed booking keeps its
         * address — somebody needs to find the place again, and by then they
         * have paid for it.
         */
        and b.starts_at - now() < interval '24 hours'
    );
$$;

revoke all on function space_access_details(uuid) from public;
grant execute on function space_access_details(uuid) to authenticated;


-- ===================================================================
-- 0028_description_editable.sql
-- ===================================================================

-- Let a host write the paragraph their listing already shows.
--
-- `spaces.description` has existed since the first migration and the listing
-- screen has always rendered it. Nothing ever collected it: not the listing
-- form, not the edit screen, and `createSpace` did not write the column. Every
-- real listing has an empty one, which is why the app looked like it had
-- descriptions — the seeded fake data did, and the fakes were what got looked
-- at.
--
-- The column needs nothing. The grant does: 0019 revoked the blanket update on
-- `spaces` and re-granted per column, so anything added after it is read-only
-- until named here.

grant update (description) on spaces to authenticated;

-- A paragraph, not an essay. Long enough for what a room is like and short
-- enough that a practitioner reads it before choosing.
alter table spaces
  drop constraint if exists spaces_description_length;
alter table spaces
  add constraint spaces_description_length check (
    description is null or length(description) <= 1200
  );


-- ===================================================================
-- 0029_space_timezone.sql
-- ===================================================================

-- A room's hours belong to the room's own city.
--
-- Availability is stored as a weekday and a minute of the day: "Tuesday, 540"
-- means Tuesday at 9am. Nowhere did it say 9am *where*, and the code turned
-- those minutes into real instants using whichever timezone the running
-- process happened to be in. In a browser that is the practitioner's zone; on
-- the server it is UTC. The phone offered 4pm Pacific, the server rebuilt the
-- same grid in UTC, the two never matched, and every booking was rejected as
-- an hour the host had not opened.
--
-- The missing fact was never in the code. It was here: a schedule of wall-clock
-- times with no zone attached cannot be converted to instants at all. So the
-- zone is stored beside the coordinates it comes from.
--
-- Derived from lat/lng rather than typed, because a host picking their own
-- address already told us where the room is, and asking them to also name a
-- timezone is asking the same question twice with more ways to get it wrong.
-- Postgres cannot do that lookup — it knows every zone's rules but not which
-- zone covers a point — so the app resolves it and writes it here.

alter table spaces
  add column if not exists timezone text not null default 'America/Los_Angeles';

-- Shape only. Whether a zone actually exists is a question for the tz database,
-- which Postgres has and the check cannot reach from a constraint, so the app
-- validates against Intl before writing. This stops the empty strings and the
-- 'PST' abbreviations, which are the mistakes that actually happen.
alter table spaces
  drop constraint if exists spaces_timezone_is_iana;

alter table spaces
  add constraint spaces_timezone_is_iana
  check (timezone ~ '^[A-Za-z][A-Za-z0-9+_-]*(/[A-Za-z0-9+_.-]+)+$');

comment on column spaces.timezone is
  'IANA zone of the room itself, e.g. America/Los_Angeles. Availability minutes '
  'are wall-clock times in this zone. Resolved from lat/lng at write time.';

-- 0019 revoked blanket update on spaces and grants one column at a time, so a
-- new column is read-only until it is named here. It changes with the address,
-- and the address is editable.
grant update (timezone) on spaces to authenticated;

-- ------------------------------------------------------------------
-- The zone is public, because the hours are.
--
-- A practitioner has to be told when the room is open before deciding to book
-- it, and a list of wall-clock hours with no zone is not an answer. It gives
-- nothing away either: the neighbourhood is already shown, and a timezone is a
-- far coarser fact than that.
--
-- Adding it here rather than relying on the column existing: the client reads
-- this view with `select *`, so a column missing from it arrives as undefined
-- and falls back to Pacific — every listing on earth quietly on one clock,
-- with nothing failing to say so.
-- ------------------------------------------------------------------
drop view if exists spaces_public;

create view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, timezone, status, created_at,
    description, amenities, requirements, house_rules,
    map_x, map_y,
    entrance_access, floor_access, doorway_inches, restroom_access,
    public_area(address_line) as area,
    approx_lat(id, lat) as approx_lat,
    approx_lng(id, lat, lng) as approx_lng
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;
grant select on spaces_public to service_role;

/*
 * The default above is a starting value for the four rows that already exist,
 * every one of them in the Bay Area. It is deliberately not a promise: the app
 * always sends a resolved zone on insert, and the day a listing is created
 * outside Pacific time without one, that listing is wrong in an obvious way
 * rather than a silent one.
 */


-- ===================================================================
-- 0030_charge_at_booking.sql
-- ===================================================================

-- The money is taken when the booking is made, and the host is paid after the
-- session. Two different moments, so two different columns.
--
-- It used to be one. The card was authorised at booking and captured at the
-- session, and Stripe split that capture between us and the host in the same
-- instant — so "captured_at" answered both "did we get paid" and "did the host
-- get paid" at once, because they were the same event.
--
-- They are not the same event any more. Charging up front means the money sits
-- with us for as long as the booking is in the future, and the host's rate is
-- transferred once the hour has actually happened. That gap is the whole
-- reason the change works: a cancellation before the session refunds out of
-- our balance and never touches an account the host has already seen money
-- arrive in.
--
-- `captured_at` keeps its meaning — the practitioner's money reached us — and
-- the rest is new.

alter table bookings
  add column if not exists host_paid_at timestamptz,
  add column if not exists stripe_transfer_id text,
  add column if not exists refunded_at timestamptz,
  add column if not exists refunded_cents integer;

comment on column bookings.captured_at is
  'When the practitioner''s card was charged. At booking now, not at the session.';
comment on column bookings.host_paid_at is
  'When the host''s rate was transferred to their connected account, after the session.';
comment on column bookings.refunded_cents is
  'What went back to the practitioner. Null when nothing did.';

-- A refund without an amount, or an amount without a refund, means one of the
-- two writes did not happen — and the payout sweep reads both.
alter table bookings
  drop constraint if exists bookings_refund_consistent;

alter table bookings
  add constraint bookings_refund_consistent
  check (
    (refunded_at is null and refunded_cents is null)
    or (refunded_at is not null and refunded_cents is not null and refunded_cents >= 0)
  );

-- Likewise: a transfer id is the receipt for the payout, and one without the
-- other would leave the sweep unable to tell a paid host from an unpaid one.
alter table bookings
  drop constraint if exists bookings_payout_consistent;

alter table bookings
  add constraint bookings_payout_consistent
  check (
    (host_paid_at is null and stripe_transfer_id is null)
    or (host_paid_at is not null and stripe_transfer_id is not null)
  );

/*
 * The sweep reads this on every run: sessions that have happened, whose money
 * we are holding, that have not been refunded and whose host has not been paid.
 */
create index if not exists bookings_awaiting_payout
  on bookings (starts_at)
  where host_paid_at is null and captured_at is not null and refunded_at is null;

-- ------------------------------------------------------------------
-- Nobody but the platform writes any of this.
--
-- 0002 granted the practitioner and host views their own columns; these are
-- ours. A host being able to write host_paid_at would be a host able to mark
-- themselves paid.
-- ------------------------------------------------------------------
revoke update (host_paid_at, stripe_transfer_id, refunded_at, refunded_cents)
  on bookings from authenticated;


-- ===================================================================
-- 0031_parking.sql
-- ===================================================================

-- Where somebody leaves the car.
--
-- A practitioner arriving by car asks three things in this order: is there
-- anywhere to park, will it cost me, and can I leave it there for the whole
-- session. The listing answered none of them, so the only way to find out was
-- to message the host and wait — or to turn up and find out.
--
-- The third question is the one that matters most here and the one a listings
-- site normally has no field for. This marketplace sells hours. A two-hour
-- street limit is fine; a one-hour limit on a one-hour session means leaving
-- mid-session to move the car, or a ticket.
--
-- Several answers at once, because a studio can have two spaces out front and
-- a street anybody can use. One choice would make the host pick the better one
-- and leave out the one somebody actually needed.

alter table spaces
  add column if not exists parking text[] not null default '{}',
  add column if not exists parking_limit_minutes integer;

comment on column spaces.parking is
  'Keys from PARKING_OPTIONS in src/lib/parking.ts. Empty means unanswered, '
  'which is shown as unanswered rather than as "no parking".';
comment on column spaces.parking_limit_minutes is
  'How long a car may stay. Null means no limit.';

-- A limit of zero or a negative one is not a stricter rule, it is a mistake.
-- The upper bound is a day: anything longer is "no limit" and belongs as null.
alter table spaces
  drop constraint if exists spaces_parking_limit_sane;

alter table spaces
  add constraint spaces_parking_limit_sane
  check (
    parking_limit_minutes is null
    or (parking_limit_minutes > 0 and parking_limit_minutes <= 1440)
  );

-- 0019 revoked the blanket update and grants per column, so a new column stays
-- read-only to its own owner until it is named here.
grant update (parking, parking_limit_minutes) on spaces to authenticated;

-- ------------------------------------------------------------------
-- Public, for the same reason the accessibility answers are.
--
-- None of it locates the room — "street parking" is true of most streets — and
-- it is read while deciding, which is before a booking exists.
--
-- Rebuilt in full rather than altered: the client reads this view with
-- `select *`, so a column missing from it arrives as undefined and the listing
-- silently shows nothing, with no error anywhere to say so.
-- ------------------------------------------------------------------
drop view if exists spaces_public;

create view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, timezone, status, created_at,
    description, amenities, requirements, house_rules,
    map_x, map_y,
    entrance_access, floor_access, doorway_inches, restroom_access,
    parking, parking_limit_minutes,
    public_area(address_line) as area,
    approx_lat(id, lat) as approx_lat,
    approx_lng(id, lat, lng) as approx_lng
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;
grant select on spaces_public to service_role;


-- ===================================================================
-- 0032_public_address.sql
-- ===================================================================

-- The address is public. How to get in is not.
--
-- Every listing here is a retail studio. Its address is on Google Maps, on its
-- own website, on the sign above the door — so withholding the street number
-- protected nothing and cost a practitioner the single fact they judge a room
-- by. "Redwood City, CA 94063" is not somewhere you can decide to go.
--
-- It was never much of a defence against booking off-platform either. One
-- booking and the address is theirs forever; what actually keeps a marketplace
-- together is that the money, the record, the cover and the terms live here.
--
-- What stays behind the booking is the part that is genuinely not public: the
-- entry instructions and the access code. "386 Convention Way" tells somebody
-- where the building is. "Side door, keypad 4021, press # after" tells them how
-- to get inside it, and that belongs to whoever paid for the hour.
--
-- So the approximate coordinates go too. They existed to draw a pin 250-450m
-- from a room we would not name; with the address published, a deliberately
-- wrong pin is just a worse map.

drop view if exists spaces_public;

create view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, timezone, status, created_at,
    description, amenities, requirements, house_rules,
    map_x, map_y,
    entrance_access, floor_access, doorway_inches, restroom_access,
    parking, parking_limit_minutes,
    -- The street, at last. Still nothing about the door.
    address_line,
    lat,
    lng,
    public_area(address_line) as area
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;
grant select on spaces_public to service_role;

/*
 * `entry_instructions` is deliberately absent, as it has always been, and
 * `space_access_details` is left exactly as 0027 wrote it: still gated on
 * holding a booking inside the 24-hour line. It now releases one thing that is
 * already published and one that is not, which is harmless — the caller reads
 * it for the instructions.
 *
 * `area` stays because the browse list uses it as a short label, and a town is
 * easier to scan than a street address in a row of cards.
 */


-- ===================================================================
-- 0033_refund_requests.sql
-- ===================================================================

-- Asking for money back, with a reason attached.
--
-- The automatic rule covers one case: cancel 24 hours ahead, get the charge
-- back. Everything else had no path. Somebody who stood outside a locked door
-- had the same options as somebody who changed their mind — none — and the
-- terms meanwhile promised a goodwill credit that no code has ever written.
--
-- A reason from a fixed list rather than a paragraph, because a reason that
-- cannot be counted cannot be compared, and a marketplace that cannot compare
-- cannot see a pattern. The paragraph is kept as well, never instead.
--
-- What this table is really for is the part after the request: the host's
-- answer, and a decision with a name on it. A refund system that pays out on
-- one unchecked story gets farmed, and the person who pays for that is a host
-- who did nothing wrong.

do $$ begin
  create type refund_reason as enum (
    'no_access', 'not_as_described', 'double_booked', 'unsafe',
    'host_no_show', 'changed_plans', 'other'
  );
exception when duplicate_object then null; end $$;

do $$ begin
  create type refund_state as enum (
    'awaiting_host', 'awaiting_staff', 'approved', 'refused'
  );
exception when duplicate_object then null; end $$;

do $$ begin
  create type refund_outcome as enum ('full', 'our_fee', 'none');
exception when duplicate_object then null; end $$;

create table if not exists refund_requests (
  id uuid primary key default gen_random_uuid(),

  -- One request per booking. Somebody who disagrees with the answer takes it
  -- up with a person; they do not get to ask again with a better reason.
  booking_id uuid not null unique references bookings (id) on delete cascade,
  practitioner_id uuid not null references profiles (id) on delete cascade,

  reason refund_reason not null,
  -- In their own words, alongside the reason rather than instead of it.
  detail text not null,
  -- Storage path, for the reasons where a photograph settles it.
  evidence_path text,

  state refund_state not null default 'awaiting_staff',

  -- The host's account of the same events. Null until they answer, and the
  -- request moves on without them after HOST_REPLY_HOURS either way.
  host_reply text,
  host_replied_at timestamptz,

  -- The decision, and who made it.
  outcome refund_outcome,
  decided_by uuid references profiles (id),
  decided_at timestamptz,
  decision_note text,
  refunded_cents integer,

  created_at timestamptz not null default now()
);

-- A decision is a decision: it has an outcome, a time and a person, or it has
-- none of them. Half-written rows are how a refund gets paid twice.
alter table refund_requests
  drop constraint if exists refund_requests_decision_complete;

alter table refund_requests
  add constraint refund_requests_decision_complete
  check (
    (state in ('awaiting_host', 'awaiting_staff')
      and outcome is null and decided_at is null and decided_by is null)
    or
    (state in ('approved', 'refused')
      and outcome is not null and decided_at is not null and decided_by is not null)
  );

-- Approved means money moved, or moved to zero deliberately. Refused never
-- pays. Stated here so a bug in the route cannot write a contradiction.
alter table refund_requests
  drop constraint if exists refund_requests_outcome_matches_state;

alter table refund_requests
  add constraint refund_requests_outcome_matches_state
  check (
    state <> 'refused' or outcome = 'none'
  );

create index if not exists refund_requests_open_idx
  on refund_requests (state, created_at)
  where state in ('awaiting_host', 'awaiting_staff');

-- The count that makes a pattern visible, without a scan per request.
create index if not exists refund_requests_by_practitioner_idx
  on refund_requests (practitioner_id, created_at desc);

-- ------------------------------------------------------------------
-- Who may see and do what.
-- ------------------------------------------------------------------
alter table refund_requests enable row level security;

drop policy if exists "practitioner reads own refund requests" on refund_requests;
create policy "practitioner reads own refund requests"
  on refund_requests for select
  using (practitioner_id = auth.uid());

/*
 * The host reads the request against their own room, and nothing else.
 *
 * They are being asked to answer an account of events, so they have to see it
 * — but through the booking they own, never by practitioner id, or a host
 * could read every request that person has ever made and answer the pattern
 * rather than the day.
 */
drop policy if exists "host reads requests on their own rooms" on refund_requests;
create policy "host reads requests on their own rooms"
  on refund_requests for select
  using (
    exists (
      select 1 from bookings b
      join spaces s on s.id = b.space_id
      where b.id = refund_requests.booking_id
        and s.host_id = auth.uid()
    )
  );

/*
 * Nobody writes here from the browser. Not the practitioner, not the host.
 *
 * Creating a request has to check the booking was paid, that the window is
 * open, and how many have been asked before; a reply has to check who is
 * replying and that it is still open to replies. All of that is the route's
 * job, on the service key. An insert policy would be a second copy of those
 * rules, kept in a different language, drifting.
 */

grant select on refund_requests to authenticated;


-- ===================================================================
-- 0034_studio_claims.sql
-- ===================================================================

-- When a studio is left worse than it was found.
--
-- The mirror of 0033, pointing the other way, and built to the same rule:
-- nobody's card is charged on one side's account of events. A host reports, the
-- practitioner answers, a person decides. Reversing that — charge first, argue
-- later — is how a marketplace collects chargebacks instead of money, and at
-- this size one chargeback costs more than the claim it was meant to recover.
--
-- What is deliberately absent is any notion of us paying. We decide and we
-- collect; we do not guarantee. If the practitioner's card fails, the host is
-- told and given the record, and it is theirs and their insurer's to pursue. A
-- marketplace that tops up failed claims out of its own margin has quietly
-- become an insurer without pricing the risk.

do $$ begin
  create type claim_kind as enum ('cleaning', 'overstay', 'damage');
exception when duplicate_object then null; end $$;

do $$ begin
  create type claim_state as enum (
    'awaiting_practitioner', 'awaiting_staff', 'upheld', 'rejected', 'uncollectable'
  );
exception when duplicate_object then null; end $$;

create table if not exists studio_claims (
  id uuid primary key default gen_random_uuid(),

  -- One claim per booking, same as a refund request. A host who disagrees with
  -- the answer takes it up with a person rather than filing again.
  booking_id uuid not null unique references bookings (id) on delete cascade,
  host_id uuid not null references profiles (id) on delete cascade,

  kind claim_kind not null,
  detail text not null,
  -- Required for cleaning and damage. Enforced in the route, where the rule
  -- that decides it also lives — see claims.ts.
  evidence_path text,

  -- Only for overstay, and only as reported. What it costs is computed from
  -- the room's own rate rather than trusted from here.
  minutes_over integer,
  -- What the host says it will cost to put right. Null for the fixed kinds.
  claimed_cents integer,

  state claim_state not null default 'awaiting_practitioner',

  -- The practitioner's account of the same session.
  practitioner_reply text,
  practitioner_replied_at timestamptz,

  -- The decision.
  charged_cents integer,
  decided_by uuid references profiles (id),
  decided_at timestamptz,
  decision_note text,
  -- Set when the decision was made but the card would not pay. The host is
  -- owed nothing by us in that case, and this is how the screen says so.
  collection_error text,

  created_at timestamptz not null default now()
);

alter table studio_claims
  drop constraint if exists studio_claims_decision_complete;

alter table studio_claims
  add constraint studio_claims_decision_complete
  check (
    (state in ('awaiting_practitioner', 'awaiting_staff')
      and decided_at is null and decided_by is null and charged_cents is null)
    or
    (state in ('upheld', 'rejected', 'uncollectable')
      and decided_at is not null and decided_by is not null)
  );

-- Rejected means nothing was taken. Uncollectable means we tried and the card
-- refused — a distinction the host needs, because one is a judgement about
-- their claim and the other is not.
alter table studio_claims
  drop constraint if exists studio_claims_charge_matches_state;

alter table studio_claims
  add constraint studio_claims_charge_matches_state
  check (
    (state = 'rejected' and coalesce(charged_cents, 0) = 0)
    or (state = 'upheld' and charged_cents > 0)
    or (state = 'uncollectable' and coalesce(charged_cents, 0) = 0
        and collection_error is not null)
    or state in ('awaiting_practitioner', 'awaiting_staff')
  );

-- A host cannot invoice for time nobody spent, or for a negative amount.
alter table studio_claims
  drop constraint if exists studio_claims_amounts_sane;

alter table studio_claims
  add constraint studio_claims_amounts_sane
  check (
    (minutes_over is null or (minutes_over > 0 and minutes_over <= 600))
    and (claimed_cents is null or (claimed_cents > 0 and claimed_cents <= 1000000))
  );

create index if not exists studio_claims_open_idx
  on studio_claims (state, created_at)
  where state in ('awaiting_practitioner', 'awaiting_staff');

create index if not exists studio_claims_by_host_idx
  on studio_claims (host_id, created_at desc);

-- ------------------------------------------------------------------
-- Who sees what.
-- ------------------------------------------------------------------
alter table studio_claims enable row level security;

drop policy if exists "host reads their own claims" on studio_claims;
create policy "host reads their own claims"
  on studio_claims for select
  using (host_id = auth.uid());

/*
 * The practitioner reads the claim against them, through the booking.
 *
 * They are being asked to answer it, so they have to see it — but never by
 * host id, or somebody could read every claim a studio has ever filed and
 * answer the pattern rather than the session.
 */
drop policy if exists "practitioner reads claims against them" on studio_claims;
create policy "practitioner reads claims against them"
  on studio_claims for select
  using (
    exists (
      select 1 from bookings b
      where b.id = studio_claims.booking_id
        and b.practitioner_id = auth.uid()
    )
  );

-- Nothing is written from a browser. Filing checks the window, the booking and
-- the evidence; replying checks who is replying and that it is still open.
-- Both are the route's job, on the service key.
grant select on studio_claims to authenticated;


-- ===================================================================
-- 0035_floor_area.sql
-- ===================================================================

-- How big the room actually is.
--
-- Capacity answers "how many people fit", which is the host's judgement about
-- their own room and varies with what they picture happening in it. A studio
-- that seats twelve for meditation seats four for movement, and the listing
-- said twelve either way.
--
-- Square feet is the fact underneath the judgement. Somebody planning a mat
-- class knows what 400 square feet means for eight people in a way that
-- "capacity 8" never tells them, and it is the number every commercial
-- listing already carries — a retail studio knows its own floor area.
--
-- Optional, because a host who does not know should say nothing rather than
-- guess. An invented measurement is worse than a missing one: somebody would
-- plan around it.

alter table spaces
  add column if not exists floor_area_sqft integer;

comment on column spaces.floor_area_sqft is
  'Usable floor area in square feet. Null when the host has not said.';

-- A room smaller than a cupboard or larger than a warehouse is a typo, and a
-- typo here is somebody arriving at a room a tenth of the size they planned
-- a class around.
alter table spaces
  drop constraint if exists spaces_floor_area_sane;

alter table spaces
  add constraint spaces_floor_area_sane
  check (floor_area_sqft is null or (floor_area_sqft >= 50 and floor_area_sqft <= 50000));

-- 0019 grants updates per column; a new one is read-only to its owner until
-- it is named here.
grant update (floor_area_sqft) on spaces to authenticated;

-- ------------------------------------------------------------------
-- Published, like every other fact somebody decides on.
--
-- Rebuilt in full rather than altered: the client reads this view with
-- `select *`, so a column missing from it arrives as undefined and the listing
-- silently shows nothing, with nothing anywhere failing to say so.
-- ------------------------------------------------------------------
drop view if exists spaces_public;

create view spaces_public as
  select
    id, host_id, name, category, hourly_rate_cents, capacity, access_type,
    accessible, restroom, buffer_minutes, timezone, status, created_at,
    description, amenities, requirements, house_rules,
    map_x, map_y,
    entrance_access, floor_access, doorway_inches, restroom_access,
    parking, parking_limit_minutes,
    floor_area_sqft,
    address_line,
    lat,
    lng,
    public_area(address_line) as area
  from spaces
  where status = 'active';

grant select on spaces_public to anon, authenticated;
grant select on spaces_public to service_role;


-- ===================================================================
-- 0036_claim_charge_id.sql
-- ===================================================================

-- What we actually charged, and where.
--
-- An upheld claim charges a practitioner's kept card off-session, and until
-- now the row recorded only the amount. Stripe returned a charge id and the
-- service threw it away, so the one irreversible act in the whole claim flow
-- was the only money movement in this app with nothing pointing at it —
-- bookings keep their payment intent, payouts keep their transfer, this kept
-- a number.
--
-- It matters at exactly the moment it is missing. Somebody disputes the
-- seventeen dollars with their bank and we have to answer with evidence tied
-- to that charge; staff decide a claim was wrong and there is nothing to
-- refund against; the month's collections have to be reconciled and there is
-- no key to join on.

alter table studio_claims
  add column if not exists stripe_payment_intent_id text;

comment on column studio_claims.stripe_payment_intent_id is
  'The off-session charge that collected this claim. Null until upheld and paid, and on any claim that was rejected or could not be collected.';

-- Written only by the service role deciding a claim. Nobody on either side of
-- a dispute may touch the record of what was charged.
revoke update (stripe_payment_intent_id) on studio_claims from authenticated;


-- ===================================================================
-- 0037_moving_a_listing.sql
-- ===================================================================

-- Moving a listing has to move everything that says where it is.
--
-- The edit screen took the address as free text and saved the string on its
-- own. `lat`, `lng` and the browse-map pair went on describing the building
-- the host used to be in, so a host who moved across town ended up with a
-- listing that read one address and behaved like another: the map a
-- practitioner opens once they have booked centred on the old street, and
-- nearby search ranked the listing by its distance from a city it had left.
--
-- The screen now resolves the address the way the listing form does and sends
-- the coordinates with it. `lat` and `lng` were already in 0019's list.
-- `map_x`/`map_y` were not — they arrived in 0008, after the blanket update
-- had been revoked and re-granted column by column, so a host could write them
-- when the listing was created and never again. The write failed on exactly
-- the path that needed it.
--
-- Granting them exposes nothing new. They are already public in
-- `spaces_public`, already written by the host at creation, and 0008's check
-- constraint keeps them inside the drawing. They are a coarse function of the
-- ~11 km cell a coordinate falls in — see `toBrowsePosition` — which is what
-- makes them safe to publish in the first place. What this permits is a host
-- keeping the decoration in step with an address they were already allowed to
-- change.

grant update (map_x, map_y) on spaces to authenticated;


-- ===================================================================
-- 0038_paid_bookings_only.sql
-- ===================================================================

-- A checkout nobody paid for is not a booking, on the host's side either.
--
-- `host_bookings()` has returned every row on a host's spaces since 0005,
-- including the ones sitting at `upcoming` with no `captured_at` — which is
-- what a booking looks like between the row being written and a card being
-- entered, and what it goes on looking like for the thirty minutes before
-- abandoned.ts reaps it.
--
-- So closing the card form put a session on a studio's calendar. The
-- practitioner side had the same hole and the same fix; this is the half that
-- lives in SQL.
--
-- The hour genuinely is held during those thirty minutes — the availability
-- check excludes anything `upcoming`, paid or not, so nobody else can take it
-- — and that is deliberate: the person at the card form should not lose the
-- slot to somebody quicker. But a held hour is not a booking. Showing it as
-- one is how a host rearranges an afternoon around a session that evaporates
-- without a word.
--
-- Cancelled and completed rows keep flowing through. They carry `captured_at`
-- because money did arrive, and a host's history should not lose a session
-- that happened.

create or replace function host_bookings()
returns table (
  booking_id uuid,
  space_id uuid,
  starts_at timestamptz,
  ends_at timestamptz,
  status booking_status,
  net_cents integer,
  -- Column names copied from 0005 exactly. Postgres refuses to replace a
  -- function whose output names differ, and renaming one here would mean a
  -- drop, which takes the grant with it.
  practitioner_name text,
  practitioner_avatar_path text
)
language sql
stable
security definer
set search_path = public
as $$
  select
    b.id,
    b.space_id,
    b.starts_at,
    b.ends_at,
    b.status,
    b.host_rate_cents,
    p.display_name,
    p.avatar_path
  from bookings b
  join spaces s on s.id = b.space_id
  join profiles p on p.id = b.practitioner_id
  where s.host_id = auth.uid()
    -- Money arrived, or it never happened.
    and b.captured_at is not null
  order by b.starts_at;
$$;

revoke all on function host_bookings() from public;
grant execute on function host_bookings() to authenticated;
